declare
 wanted jsonb := $review_papers$[{"id":"tcf-listening-03","version":"tcf-listening-2026-11-test03-v3","title":"TCF Listening · Test 03","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Le professionnel indique une ligne sur l'ordonnance que la cliente tient devant lui.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Le pharmacien explique une ordonnance à une cliente. B. La cliente signe un formulaire de livraison. C. Le pharmacien remet un colis à une cliente. D. La cliente demande où se trouve le médecin.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le pharmacien explique une ordonnance à une cliente. B. La cliente signe un formulaire de livraison. C. Le pharmacien remet un colis à une cliente. D. La cliente demande où se trouve le médecin."}],"audio":"q-01.mp3","audioSeconds":20.126,"slotSeconds":34,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La patiente consulte le numéro lumineux affiché au-dessus des sièges.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Une patiente remplit un dossier au guichet. B. Une patiente règle une facture au secrétariat. C. Une patiente vérifie son numéro sur l'écran. D. Une patiente demande un rendez-vous à l'accueil.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une patiente remplit un dossier au guichet. B. Une patiente règle une facture au secrétariat. C. Une patiente vérifie son numéro sur l'écran. D. Une patiente demande un rendez-vous à l'accueil."}],"audio":"q-02.mp3","audioSeconds":19.104,"slotSeconds":32,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'infirmière fait une démonstration du port de gants à une autre personne.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. L'infirmière vérifie une prescription avec son collègue. B. L'infirmière montre un geste d'hygiène à son collègue. C. L'infirmière prépare une injection devant son collègue. D. L'infirmière met ses gants après une consultation.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'infirmière vérifie une prescription avec son collègue. B. L'infirmière montre un geste d'hygiène à son collègue. C. L'infirmière prépare une injection devant son collègue. D. L'infirmière met ses gants après une consultation."}],"audio":"q-03.mp3","audioSeconds":21.438,"slotSeconds":35,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Le brassard et le tensiomètre servent à mesurer la pression artérielle.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Le médecin mesure la température de son patient. B. Le patient règle lui-même le bracelet de son appareil. C. Le médecin examine une blessure sur le bras du patient. D. Le médecin vérifie la tension artérielle de son patient.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le médecin mesure la température de son patient. B. Le patient règle lui-même le bracelet de son appareil. C. Le médecin examine une blessure sur le bras du patient. D. Le médecin vérifie la tension artérielle de son patient."}],"audio":"q-04.mp3","audioSeconds":20.997,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'employée répond à la disponibilité des résultats, et précise que ce sera demain.","transcript":"Question 5.\nBonjour, je peux venir chercher mes résultats d'analyse aujourd'hui ?\nA. Ils sont conservés à l'hôpital depuis lundi. B. Ils doivent être présentés avant votre rendez-vous. C. Ils seront disponibles demain dès neuf heures. D. Ils ont été prélevés ce matin à neuf heures.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Bonjour, je peux venir chercher mes résultats d'analyse aujourd'hui ?"},{"voice":"male","text":"A. Ils sont conservés à l'hôpital depuis lundi. B. Ils doivent être présentés avant votre rendez-vous. C. Ils seront disponibles demain dès neuf heures. D. Ils ont été prélevés ce matin à neuf heures."}],"audio":"q-05.mp3","audioSeconds":21.519,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse utile à une erreur de date est de demander un autre rendez-vous.","transcript":"Question 6.\nJe me suis trompé de jour pour mon rendez-vous. Que dois-je faire ?\nA. Présentez-vous un quart d'heure avant l'heure prévue. B. Téléphonez à l'accueil pour demander un autre créneau. C. Attendez près de la porte jusqu'à l'arrivée du médecin. D. Gardez le reçu de paiement jusqu'à votre prochaine visite.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Je me suis trompé de jour pour mon rendez-vous. Que dois-je faire ?"},{"voice":"female","text":"A. Présentez-vous un quart d'heure avant l'heure prévue. B. Téléphonez à l'accueil pour demander un autre créneau. C. Attendez près de la porte jusqu'à l'arrivée du médecin. D. Gardez le reçu de paiement jusqu'à votre prochaine visite."}],"audio":"q-06.mp3","audioSeconds":21.693,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La proposition A annonce un rappel de la médecin : elle confirme donc une consultation par téléphone. Les autres réponses concernent l'ouverture, la durée ou un document à apporter.","transcript":"Question 7.\nLa consultation peut-elle se faire par téléphone ?\nA. Oui, la médecin vous rappellera. B. Oui, le cabinet reçoit encore. C. Elle dure environ vingt minutes. D. Apportez une ordonnance du médecin.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"La consultation peut-elle se faire par téléphone ?"},{"voice":"male","text":"A. Oui, la médecin vous rappellera. B. Oui, le cabinet reçoit encore. C. Elle dure environ vingt minutes. D. Apportez une ordonnance du médecin."}],"audio":"q-07.mp3","audioSeconds":18.521,"slotSeconds":32},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse fournit de nouveau le numéro demandé, plutôt qu'une information secondaire.","transcript":"Question 8.\nJ'ai perdu la carte avec le numéro du cabinet. Vous pouvez m'aider ?\nA. Vous pouvez reporter le rendez-vous au mois prochain. B. Vous pouvez laisser vos affaires à la réception. C. Vous trouverez les tarifs sur la porte d'entrée. D. Je vais vous écrire le numéro sur une feuille.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"J'ai perdu la carte avec le numéro du cabinet. Vous pouvez m'aider ?"},{"voice":"female","text":"A. Vous pouvez reporter le rendez-vous au mois prochain. B. Vous pouvez laisser vos affaires à la réception. C. Vous trouverez les tarifs sur la porte d'entrée. D. Je vais vous écrire le numéro sur une feuille."}],"audio":"q-08.mp3","audioSeconds":20.9,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Où les patients doivent-ils se présenter ce matin ?","options":["Au premier étage, près du bureau douze.","Au rez-de-chaussée, près du bureau douze.","Au rez-de-chaussée, près du bureau quatorze.","Au premier étage, près du bureau quatorze."],"correct":"A","explanation":"L'accueil temporaire se trouve au premier étage, vers le bureau douze.","transcript":"Question 9.\nL'accueil des consultations est déplacé ce matin. Les urgences restent au rez-de-chaussée. Pour votre rendez-vous, montez au premier étage par l'escalier de droite. Un agent vous attend devant le bureau douze. Demain, l'accueil retrouvera son emplacement habituel.\nOù les patients doivent-ils se présenter ce matin ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"L'accueil des consultations est déplacé ce matin. Les urgences restent au rez-de-chaussée. Pour votre rendez-vous, montez au premier étage par l'escalier de droite. Un agent vous attend devant le bureau douze. Demain, l'accueil retrouvera son emplacement habituel."},{"voice":"female","text":"Où les patients doivent-ils se présenter ce matin ?"}],"audio":"q-09.mp3","audioSeconds":20.663,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi la cliente ne repart-elle pas avec son traitement habituel ?","options":["Elle préfère un traitement de dosage différent.","Elle veut vérifier la substitution avec son médecin.","Elle attend un appel sur les délais de livraison.","Elle a perdu le renouvellement de son ordonnance."],"correct":"B","explanation":"Elle ne souhaite pas accepter le générique sans confirmation médicale.","transcript":"Question 10.\nBonjour, je viens renouveler mon traitement. Voici mon ordonnance.\nNous n'avons plus les comprimés de cette marque, mais le même dosage existe en générique.\nMa médecin m'avait recommandé de ne pas changer sans la prévenir.\nDans ce cas, je peux réserver une boîte pour demain et contacter son cabinet pour vérifier la substitution.\nJe préfère cette solution, merci.\nPourquoi la cliente ne repart-elle pas avec son traitement habituel ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"Bonjour, je viens renouveler mon traitement. Voici mon ordonnance."},{"voice":"male","text":"Nous n'avons plus les comprimés de cette marque, mais le même dosage existe en générique."},{"voice":"female","text":"Ma médecin m'avait recommandé de ne pas changer sans la prévenir."},{"voice":"male","text":"Dans ce cas, je peux réserver une boîte pour demain et contacter son cabinet pour vérifier la substitution."},{"voice":"female","text":"Je préfère cette solution, merci."},{"voice":"female","text":"Pourquoi la cliente ne repart-elle pas avec son traitement habituel ?"}],"audio":"q-10.mp3","audioSeconds":29.173,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Quel document doit-on présenter lors du don ?","options":["Une pièce d'identité avec photographie.","Le questionnaire de santé signé à l'avance.","Un certificat du médecin datant de moins d'un mois.","Le courriel portant le numéro de réservation."],"correct":"A","explanation":"La pièce d'identité avec photo est exigée; les autres documents ne le sont pas.","transcript":"Question 11.\nLe centre de collecte remercie les personnes inscrites à la séance de samedi. Afin de faciliter l'enregistrement, présentez une pièce d'identité avec photographie. Le questionnaire de santé pourra être rempli sur place. Il n'est pas nécessaire d'imprimer le courriel de confirmation, mais pensez à respecter l'heure de votre réservation.\nQuel document doit-on présenter lors du don ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Le centre de collecte remercie les personnes inscrites à la séance de samedi. Afin de faciliter l'enregistrement, présentez une pièce d'identité avec photographie. Le questionnaire de santé pourra être rempli sur place. Il n'est pas nécessaire d'imprimer le courriel de confirmation, mais pensez à respecter l'heure de votre réservation."},{"voice":"female","text":"Quel document doit-on présenter lors du don ?"}],"audio":"q-11.mp3","audioSeconds":25.815,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quel arrangement les deux personnes choisissent-elles ?","options":["Un passage à la place du village en matinée.","Un rendez-vous au domicile du fils mercredi matin.","Un transport vers le cabinet mardi après-midi.","Une consultation à la résidence dans l'après-midi."],"correct":"D","explanation":"Ils retiennent la permanence de quinze heures à la résidence.","transcript":"Question 12.\nLe camion de consultation sera au village mardi, mais ma mère ne peut pas se déplacer seule jusqu'à la place.\nIl passera ensuite à la résidence, à quinze heures.\nC'est beaucoup plus simple. Est-ce que je dois appeler pour réserver ?\nOui, demandez un rendez-vous pour la permanence à la résidence. Elle n'aura pas besoin de venir au centre du village.\nQuel arrangement les deux personnes choisissent-elles ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Le camion de consultation sera au village mardi, mais ma mère ne peut pas se déplacer seule jusqu'à la place."},{"voice":"female","text":"Il passera ensuite à la résidence, à quinze heures."},{"voice":"male","text":"C'est beaucoup plus simple. Est-ce que je dois appeler pour réserver ?"},{"voice":"female","text":"Oui, demandez un rendez-vous pour la permanence à la résidence. Elle n'aura pas besoin de venir au centre du village."},{"voice":"female","text":"Quel arrangement les deux personnes choisissent-elles ?"}],"audio":"q-12.mp3","audioSeconds":27.309,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Pourquoi le rendez-vous de vaccination est-il reporté ?","options":["Une livraison arrivée après l'heure des rendez-vous.","Une quantité de doses reçues inférieure aux besoins.","Un changement de personnel prévu en milieu de semaine.","Une commande passée dans le mauvais établissement."],"correct":"B","explanation":"Le report résulte d'une livraison de doses incomplète.","transcript":"Question 13.\nNous informons les personnes inscrites à la campagne de vaccination de mercredi que les injections auront lieu vendredi aux mêmes horaires. La livraison de doses attendue lundi est arrivée incomplète et un nouveau lot sera disponible jeudi. Toutes les réservations sont conservées; aucun nouvel enregistrement n'est nécessaire.\nPourquoi le rendez-vous de vaccination est-il reporté ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Nous informons les personnes inscrites à la campagne de vaccination de mercredi que les injections auront lieu vendredi aux mêmes horaires. La livraison de doses attendue lundi est arrivée incomplète et un nouveau lot sera disponible jeudi. Toutes les réservations sont conservées; aucun nouvel enregistrement n'est nécessaire."},{"voice":"female","text":"Pourquoi le rendez-vous de vaccination est-il reporté ?"}],"audio":"q-13.mp3","audioSeconds":22.75,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle consigne l'infirmière donne-t-elle au parent ?","options":["Demander un avis médical et rester attentive à l'évolution.","Se présenter immédiatement aux urgences malgré l'état stable.","Changer la posologie avant de contacter le médecin.","Se rendre au cabinet seulement si la fièvre dure longtemps."],"correct":"A","explanation":"L'infirmière demande un avis médical aujourd'hui et indique des signes d'urgence.","transcript":"Question 14.\nMa fille a de la fièvre depuis hier. Elle boit encore, mais elle est très fatiguée. Dois-je venir tout de suite ?\nJe ne peux pas poser un diagnostic par téléphone. Surveillez son état et contactez votre médecin aujourd'hui. Si elle respire difficilement ou devient difficile à réveiller, appelez immédiatement les secours.\nJe comprends. Je vais téléphoner à son cabinet.\nQuelle consigne l'infirmière donne-t-elle au parent ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Ma fille a de la fièvre depuis hier. Elle boit encore, mais elle est très fatiguée. Dois-je venir tout de suite ?"},{"voice":"female","text":"Je ne peux pas poser un diagnostic par téléphone. Surveillez son état et contactez votre médecin aujourd'hui. Si elle respire difficilement ou devient difficile à réveiller, appelez immédiatement les secours."},{"voice":"male","text":"Je comprends. Je vais téléphoner à son cabinet."},{"voice":"female","text":"Quelle consigne l'infirmière donne-t-elle au parent ?"}],"audio":"q-14.mp3","audioSeconds":29.7,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quel est l'objectif principal du dispositif présenté ?","options":["Mieux suivre les prises et signaler les soucis au médecin.","Faire intervenir le pharmacien à la place du médecin traitant.","Changer les doses selon les observations recueillies en pharmacie.","Réorienter les patients vers un nouveau traitement systématique."],"correct":"A","explanation":"Le service vise l'observance et la transmission d'informations au médecin, pas le remplacement du prescripteur.","transcript":"Question 15.\nDans les nouvelles de santé locale, cinq pharmacies vont proposer un suivi régulier aux personnes sous plusieurs traitements. Les pharmaciens ne modifieront pas les prescriptions. Ils vérifieront avec les patients les horaires de prise, les oublis fréquents et les éventuelles difficultés à comprendre les notices, puis transmettront leurs observations au médecin traitant avec l'accord des intéressés. Une évaluation aura lieu au printemps.\nQuel est l'objectif principal du dispositif présenté ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Dans les nouvelles de santé locale, cinq pharmacies vont proposer un suivi régulier aux personnes sous plusieurs traitements. Les pharmaciens ne modifieront pas les prescriptions. Ils vérifieront avec les patients les horaires de prise, les oublis fréquents et les éventuelles difficultés à comprendre les notices, puis transmettront leurs observations au médecin traitant avec l'accord des intéressés. Une évaluation aura lieu au printemps."},{"voice":"female","text":"Quel est l'objectif principal du dispositif présenté ?"}],"audio":"q-15.mp3","audioSeconds":29.878,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi la séance de conseil nutritionnel est-elle raccourcie ?","options":["La professionnelle doit assurer une autre visite après la séance.","Une urgence médicale retarde toutes les consultations du jeudi.","Le patient souhaite écourter les échanges sur ses habitudes.","Le dossier de la patiente exige un examen complémentaire."],"correct":"A","explanation":"La professionnelle doit assurer une autre visite, et propose un échange complémentaire.","transcript":"Question 16.\nLe rendez-vous de jeudi durera finalement trente minutes au lieu de quarante-cinq.\nEst-ce à cause du nombre de patients ?\nNon, la diététicienne assurera aussi une visite dans un foyer après son service. Nous garderons l'entretien sur vos habitudes alimentaires et prévoirons un second échange à distance pour les questions complémentaires.\nD'accord, je préparerai mon carnet de repas.\nPourquoi la séance de conseil nutritionnel est-elle raccourcie ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Le rendez-vous de jeudi durera finalement trente minutes au lieu de quarante-cinq."},{"voice":"male","text":"Est-ce à cause du nombre de patients ?"},{"voice":"female","text":"Non, la diététicienne assurera aussi une visite dans un foyer après son service. Nous garderons l'entretien sur vos habitudes alimentaires et prévoirons un second échange à distance pour les questions complémentaires."},{"voice":"male","text":"D'accord, je préparerai mon carnet de repas."},{"voice":"female","text":"Pourquoi la séance de conseil nutritionnel est-elle raccourcie ?"}],"audio":"q-16.mp3","audioSeconds":28.174,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Par quelle entrée faut-il rejoindre le cabinet ?","options":["Par l'entrée du personnel derrière la réception.","Par l'entrée située directement sur l'avenue.","Par la porte des consultations d'urgence de l'établissement.","Par l'accès de la cour depuis la rue des Écoles."],"correct":"D","explanation":"L'accès temporaire se fait par la cour depuis la rue des Écoles.","transcript":"Question 17.\nEn raison des travaux devant le cabinet des Acacias, la porte principale donnant sur l'avenue sera fermée jusqu'à vendredi. Les patients doivent entrer par la cour intérieure, accessible depuis la rue des Écoles. La signalisation a été installée ce matin, et la réception est assurée normalement.\nPar quelle entrée faut-il rejoindre le cabinet ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"En raison des travaux devant le cabinet des Acacias, la porte principale donnant sur l'avenue sera fermée jusqu'à vendredi. Les patients doivent entrer par la cour intérieure, accessible depuis la rue des Écoles. La signalisation a été installée ce matin, et la réception est assurée normalement."},{"voice":"female","text":"Par quelle entrée faut-il rejoindre le cabinet ?"}],"audio":"q-17.mp3","audioSeconds":23.179,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la secrétaire propose-t-elle un nouvel appel ?","options":["La consultation doit être validée auprès du médecin référent.","Le patient souhaite un autre spécialiste dans le même service.","Une erreur possible d'attribution de dossier doit être contrôlée.","Le secrétariat doit confirmer l'horaire d'un rendez-vous prévu."],"correct":"C","explanation":"Le patient mentionne une spécialité différente de sa demande; un rappel permettra de vérifier.","transcript":"Question 18.\nCabinet du docteur Perrin, bonjour.\nJe viens d'avoir un message pour un rendez-vous en cardiologie, mais j'avais demandé la dermatologie.\nJe vois deux dossiers au même nom. Je préfère vérifier votre date de naissance sans discuter de renseignements médicaux au téléphone. Le secrétariat spécialisé pourra vous rappeler dans l'heure.\nTrès bien, je garde mon téléphone près de moi.\nPourquoi la secrétaire propose-t-elle un nouvel appel ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Cabinet du docteur Perrin, bonjour."},{"voice":"male","text":"Je viens d'avoir un message pour un rendez-vous en cardiologie, mais j'avais demandé la dermatologie."},{"voice":"female","text":"Je vois deux dossiers au même nom. Je préfère vérifier votre date de naissance sans discuter de renseignements médicaux au téléphone. Le secrétariat spécialisé pourra vous rappeler dans l'heure."},{"voice":"male","text":"Très bien, je garde mon téléphone près de moi."},{"voice":"female","text":"Pourquoi la secrétaire propose-t-elle un nouvel appel ?"}],"audio":"q-18.mp3","audioSeconds":28.116,"slotSeconds":47},{"number":19,"kind":"announcement","question":"Quelle activité aura lieu en dehors du bâtiment ?","options":["Une séance sur les habitudes alimentaires dans la salle bleue.","Une marche encadrée sur les chemins du parc voisin.","Une discussion avec les intervenants dans le hall d'accueil.","Une démonstration du matériel de prévention sous le préau."],"correct":"B","explanation":"La marche accompagnée se déroulera dans le parc.","transcript":"Question 19.\nLa journée de prévention de samedi proposera des démonstrations à l'intérieur du centre et une courte marche accompagnée dans le parc voisin. Les conseils sur l'alimentation auront lieu dans la salle bleue. En cas de forte pluie, seule la marche sera remplacée par une séance de mobilité sous le préau.\nQuelle activité aura lieu en dehors du bâtiment ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"La journée de prévention de samedi proposera des démonstrations à l'intérieur du centre et une courte marche accompagnée dans le parc voisin. Les conseils sur l'alimentation auront lieu dans la salle bleue. En cas de forte pluie, seule la marche sera remplacée par une séance de mobilité sous le préau."},{"voice":"female","text":"Quelle activité aura lieu en dehors du bâtiment ?"}],"audio":"q-19.mp3","audioSeconds":21.624,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Qu'est-ce qui inquiète surtout la patiente ?","options":["Elle craint de manquer les séances de rééducation à domicile.","Elle s'inquiète des douleurs pendant les prochaines séances.","Elle craint les escaliers de son immeuble au retour des soins.","Elle redoute les longs trajets pour se rendre au cabinet."],"correct":"C","explanation":"La patiente craint les escaliers de son immeuble alors qu'elle reprend la marche.","transcript":"Question 20.\nLes résultats sont encourageants. Vous pourrez bientôt reprendre la marche.\nJe suis soulagée, mais j'habite au quatrième étage et l'ascenseur tombe régulièrement en panne.\nDans ce cas, commençons par de petits trajets sur terrain plat et prévoyons une évaluation avec la kinésithérapeute.\nOui, je ne veux pas me retrouver bloquée dans l'escalier.\nQu'est-ce qui inquiète surtout la patiente ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Les résultats sont encourageants. Vous pourrez bientôt reprendre la marche."},{"voice":"female","text":"Je suis soulagée, mais j'habite au quatrième étage et l'ascenseur tombe régulièrement en panne."},{"voice":"male","text":"Dans ce cas, commençons par de petits trajets sur terrain plat et prévoyons une évaluation avec la kinésithérapeute."},{"voice":"female","text":"Oui, je ne veux pas me retrouver bloquée dans l'escalier."},{"voice":"female","text":"Qu'est-ce qui inquiète surtout la patiente ?"}],"audio":"q-20.mp3","audioSeconds":26.752,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pourquoi demande-t-on aux bénévoles de préciser leurs horaires ?","options":["Pour diminuer les permanences qui attirent le moins de patients.","Pour organiser les duos de bénévoles selon leur expérience.","Pour adapter le nombre de consultations aux médecins présents.","Pour maintenir un accueil suffisant à tous les horaires."],"correct":"D","explanation":"L'association veut couvrir les périodes moins bien pourvues, surtout le soir.","transcript":"Question 21.\nL'équipe de la clinique associative prépare les permanences de la semaine prochaine. Les bénévoles qui souhaitent aider à l'accueil sont invités à indiquer leurs créneaux exacts d'ici jeudi. Plusieurs personnes sont disponibles le matin, mais très peu en fin de journée. Nous devons répartir les présences pour ne pas laisser les patients sans orientation lorsque les salariés terminent leur service.\nPourquoi demande-t-on aux bénévoles de préciser leurs horaires ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"male","text":"L'équipe de la clinique associative prépare les permanences de la semaine prochaine. Les bénévoles qui souhaitent aider à l'accueil sont invités à indiquer leurs créneaux exacts d'ici jeudi. Plusieurs personnes sont disponibles le matin, mais très peu en fin de journée. Nous devons répartir les présences pour ne pas laisser les patients sans orientation lorsque les salariés terminent leur service."},{"voice":"female","text":"Pourquoi demande-t-on aux bénévoles de préciser leurs horaires ?"}],"audio":"q-21.mp3","audioSeconds":28.938,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel enjeu le médecin estime-t-il prioritaire ?","options":["Assurer le suivi des patients après le passage du camion.","Augmenter la fréquence des visites dans les petites communes.","Faciliter la prise du premier rendez-vous dans chaque village.","Déplacer davantage de spécialistes vers le cabinet mobile."],"correct":"A","explanation":"Le médecin insiste sur la continuité des soins après la consultation initiale.","transcript":"Question 22.\nVotre équipe se rend dans les villages éloignés avec un cabinet mobile. Qu'est-ce qui vous paraît le plus difficile ?\nLa distance est un obstacle, bien sûr, mais on se tromperait en comptant seulement le nombre de visites. Une consultation ponctuelle peut repérer un problème sans assurer la suite. Nous devons transmettre le dossier avec le consentement du patient, vérifier qu'il a trouvé un professionnel près de chez lui et l'aider lorsqu'un examen complémentaire est nécessaire. Sans cette continuité, le passage du camion devient une bonne intention dont les effets restent limités.\nQuel enjeu le médecin estime-t-il prioritaire ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Votre équipe se rend dans les villages éloignés avec un cabinet mobile. Qu'est-ce qui vous paraît le plus difficile ?"},{"voice":"female","text":"La distance est un obstacle, bien sûr, mais on se tromperait en comptant seulement le nombre de visites. Une consultation ponctuelle peut repérer un problème sans assurer la suite. Nous devons transmettre le dossier avec le consentement du patient, vérifier qu'il a trouvé un professionnel près de chez lui et l'aider lorsqu'un examen complémentaire est nécessaire. Sans cette continuité, le passage du camion devient une bonne intention dont les effets restent limités."},{"voice":"female","text":"Quel enjeu le médecin estime-t-il prioritaire ?"}],"audio":"q-22.mp3","audioSeconds":38.621,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Quelle mesure les participants finissent-ils par soutenir ?","options":["Réserver le premier entretien aux seuls cas les plus urgents.","Rediriger les demandes douteuses directement vers les urgences.","Faire utiliser une liste automatique sans contrôle infirmier.","Tester un tri humain avec vérification des appels incertains."],"correct":"D","explanation":"Le compromis prévoit un premier tri humain, une réorientation et un suivi des erreurs.","transcript":"Question 23.\nNotre débat porte sur les appels non urgents qui encombrent la ligne de conseil. Le docteur Martin propose un premier tri téléphonique.\nOui, mais je refuse un questionnaire automatique qui déciderait seul de l'orientation. Certains symptômes s'expliquent mal en quelques mots.\nEn tant que responsable du centre, je crains aussi d'allonger l'attente au téléphone.\nNous pourrions former une petite équipe à poser des questions initiales, puis transférer rapidement les situations incertaines à un infirmier.\nD'accord, si nous vérifions les appels mal orientés pendant les premières semaines.\nQuelle mesure les participants finissent-ils par soutenir ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Notre débat porte sur les appels non urgents qui encombrent la ligne de conseil. Le docteur Martin propose un premier tri téléphonique.","speaker":"female"},{"voice":"male","text":"Oui, mais je refuse un questionnaire automatique qui déciderait seul de l'orientation. Certains symptômes s'expliquent mal en quelques mots.","speaker":"male"},{"voice":"female","text":"En tant que responsable du centre, je crains aussi d'allonger l'attente au téléphone.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions former une petite équipe à poser des questions initiales, puis transférer rapidement les situations incertaines à un infirmier.","speaker":"male"},{"voice":"female","text":"D'accord, si nous vérifions les appels mal orientés pendant les premières semaines.","speaker":"female_alt"},{"voice":"female","text":"Quelle mesure les participants finissent-ils par soutenir ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":41.561,"slotSeconds":71},{"number":24,"kind":"interview","question":"Quelle limite de l'enquête reconnaît la chercheuse ?","options":["Elle a exclu les rendez-vous pris plusieurs mois auparavant.","Elle a retenu davantage de professionnels que d'usagers.","Elle n'a interrogé que les personnes inscrites sur l'application.","Elle a interrogé surtout les patients venus en personne."],"correct":"C","explanation":"L'enquête porte sur les personnes ayant réussi à créer un compte et à réserver. Elle exclut celles qui ont abandonné la procédure. Aucun passage ne parle d'exclure des rendez-vous anciens.","transcript":"Question 24.\nVotre étude conclut que l'application de prise de rendez-vous plaît beaucoup aux patients. Est-ce suffisant pour généraliser le système ?\nNous n'avons interrogé que les personnes qui ont réussi à créer un compte et à réserver. Nous savons donc ce qu'elles pensent de l'outil, pas ce que vivent les patients qui abandonnent devant la procédure. Des personnes âgées ou mal équipées peuvent être absentes de nos résultats. Notre prochaine enquête se fera aussi dans les salles d'attente, auprès de ceux qui continuent à téléphoner ou à venir au guichet.\nQuelle limite de l'enquête reconnaît la chercheuse ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre étude conclut que l'application de prise de rendez-vous plaît beaucoup aux patients. Est-ce suffisant pour généraliser le système ?"},{"voice":"female","text":"Nous n'avons interrogé que les personnes qui ont réussi à créer un compte et à réserver. Nous savons donc ce qu'elles pensent de l'outil, pas ce que vivent les patients qui abandonnent devant la procédure. Des personnes âgées ou mal équipées peuvent être absentes de nos résultats. Notre prochaine enquête se fera aussi dans les salles d'attente, auprès de ceux qui continuent à téléphoner ou à venir au guichet."},{"voice":"female","text":"Quelle limite de l'enquête reconnaît la chercheuse ?"}],"audio":"q-24.mp3","audioSeconds":34.745,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Quelle difficulté principale apparaît dans ce reportage ?","options":["Les médecins ne disposent pas de suffisamment de plages vidéo.","Les appareils imposent des examens supplémentaires non prévus.","Les cabines sont installées dans des endroits difficiles d'accès.","Les séances vidéo exigent une aide technique parfois absente."],"correct":"D","explanation":"Le service souffre surtout d'un manque d'accompagnement pour les usagers.","transcript":"Question 25.\nÀ Saint-Malo, deux cabines de téléconsultation ont été installées dans des bâtiments municipaux. Elles permettent de mesurer certains paramètres avant une consultation vidéo.\nJ'ai essayé, raconte une habitante, mais je n'ai pas compris comment régler la caméra. Un agent m'a aidée, sinon je serais repartie.\nLa commune se félicite des créneaux supplémentaires, mais admet que les appareils restent souvent inutilisés le soir, quand le personnel d'accompagnement n'est plus présent. Elle envisage donc une formation des médiateurs plutôt que l'achat immédiat de nouvelles cabines.\nQuelle difficulté principale apparaît dans ce reportage ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"À Saint-Malo, deux cabines de téléconsultation ont été installées dans des bâtiments municipaux. Elles permettent de mesurer certains paramètres avant une consultation vidéo."},{"voice":"male","text":"J'ai essayé, raconte une habitante, mais je n'ai pas compris comment régler la caméra. Un agent m'a aidée, sinon je serais repartie."},{"voice":"female","text":"La commune se félicite des créneaux supplémentaires, mais admet que les appareils restent souvent inutilisés le soir, quand le personnel d'accompagnement n'est plus présent. Elle envisage donc une formation des médiateurs plutôt que l'achat immédiat de nouvelles cabines."},{"voice":"female","text":"Quelle difficulté principale apparaît dans ce reportage ?"}],"audio":"q-25.mp3","audioSeconds":39.11,"slotSeconds":71},{"number":26,"kind":"interview","question":"Pourquoi la kinésithérapeute hésite-t-elle à acheter un nouvel appareil ?","options":["Elle souhaite confronter les fonctions de l'appareil aux besoins réels.","Elle veut d'abord comparer les frais de transport des équipements.","Elle souhaite attendre que le robot remplace les séances individuelles.","Elle préfère acquérir un modèle conçu pour une clientèle sportive."],"correct":"A","explanation":"Elle veut vérifier l'adéquation du matériel aux besoins réels.","transcript":"Question 26.\nVotre cabinet pourrait bénéficier d'un robot de rééducation. Pourquoi attendre ?\nL'appareil promet des exercices précis, mais nous recevons des patients qui ont des objectifs très différents. Certains ont besoin d'un soutien pour se relever, d'autres veulent retrouver un geste de la vie quotidienne. Avant d'investir, je souhaite observer si les exercices proposés correspondent à ces besoins et si l'équipe pourra adapter les séances. Un matériel impressionnant ne remplace ni l'évaluation clinique ni la relation avec le patient.\nPourquoi la kinésithérapeute hésite-t-elle à acheter un nouvel appareil ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Votre cabinet pourrait bénéficier d'un robot de rééducation. Pourquoi attendre ?"},{"voice":"female","text":"L'appareil promet des exercices précis, mais nous recevons des patients qui ont des objectifs très différents. Certains ont besoin d'un soutien pour se relever, d'autres veulent retrouver un geste de la vie quotidienne. Avant d'investir, je souhaite observer si les exercices proposés correspondent à ces besoins et si l'équipe pourra adapter les séances. Un matériel impressionnant ne remplace ni l'évaluation clinique ni la relation avec le patient."},{"voice":"female","text":"Pourquoi la kinésithérapeute hésite-t-elle à acheter un nouvel appareil ?"}],"audio":"q-26.mp3","audioSeconds":38.006,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quelle organisation des soins à domicile est retenue ?","options":["Déplacer toutes les visites de la semaine en fin de matinée.","Reporter la rééducation tant que les visites restent quotidiennes.","Remplacer les soins du lundi et jeudi par un rendez-vous vidéo.","Modifier deux passages infirmiers pour éviter un chevauchement."],"correct":"D","explanation":"Seuls les lundis et jeudis sont décalés à dix heures.","transcript":"Question 27.\nVotre père sort demain, mais le passage infirmier était prévu chaque matin à huit heures.\nIl a une séance de rééducation à la même heure les lundis et jeudis. Peut-on éviter le chevauchement ?\nJe peux demander un passage à dix heures ces deux jours-là et conserver huit heures le reste de la semaine.\nCela lui permettra de suivre les deux soins sans se presser.\nJe note la modification dans le planning partagé.\nQuelle organisation des soins à domicile est retenue ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Votre père sort demain, mais le passage infirmier était prévu chaque matin à huit heures."},{"voice":"male","text":"Il a une séance de rééducation à la même heure les lundis et jeudis. Peut-on éviter le chevauchement ?"},{"voice":"female","text":"Je peux demander un passage à dix heures ces deux jours-là et conserver huit heures le reste de la semaine."},{"voice":"male","text":"Cela lui permettra de suivre les deux soins sans se presser."},{"voice":"female","text":"Je note la modification dans le planning partagé."},{"voice":"female","text":"Quelle organisation des soins à domicile est retenue ?"}],"audio":"q-27.mp3","audioSeconds":29.789,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quel changement la responsable recommande-t-elle pour mieux informer les patients ?","options":["Raccourcir les notices et accélérer leur lecture en consultation.","Faire reformuler les instructions pour en vérifier la compréhension.","Remplacer les consignes individuelles par des vidéos standardisées.","Ajouter des termes médicaux dans chaque langue utilisée."],"correct":"B","explanation":"La responsable propose de faire reformuler les consignes.","transcript":"Question 28.\nLes notices traduites existent, pourtant certains patients ne suivent pas correctement leur traitement. Comment l'expliquez-vous ?\nLa traduction seule ne suffit pas. Nos documents contiennent des abréviations médicales et des phrases complexes, même dans la langue maternelle des personnes. Il faut vérifier ce qu'elles ont compris, utiliser des schémas lorsque c'est utile et laisser un temps pour les questions. Nous formons aussi les professionnels à demander au patient de reformuler les consignes avec ses propres mots. Ce n'est pas un examen, c'est une vérification de notre manière d'expliquer.\nQuel changement la responsable recommande-t-elle pour mieux informer les patients ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Les notices traduites existent, pourtant certains patients ne suivent pas correctement leur traitement. Comment l'expliquez-vous ?"},{"voice":"female","text":"La traduction seule ne suffit pas. Nos documents contiennent des abréviations médicales et des phrases complexes, même dans la langue maternelle des personnes. Il faut vérifier ce qu'elles ont compris, utiliser des schémas lorsque c'est utile et laisser un temps pour les questions. Nous formons aussi les professionnels à demander au patient de reformuler les consignes avec ses propres mots. Ce n'est pas un examen, c'est une vérification de notre manière d'expliquer."},{"voice":"female","text":"Quel changement la responsable recommande-t-elle pour mieux informer les patients ?"}],"audio":"q-28.mp3","audioSeconds":38.685,"slotSeconds":66},{"number":29,"kind":"debate","question":"Sur quoi porte essentiellement le désaccord ?","options":["Autoriser le partage des analyses uniquement en cas d'urgence.","Transmettre les dossiers entre spécialistes sans nouvelle vérification.","Limiter l'échange de résultats aux seuls services du même hôpital.","Permettre aux patients de contrôler l'accès à leurs données."],"correct":"D","explanation":"Le désaccord concerne la maîtrise des accès par les patients.","transcript":"Question 29.\nLes hôpitaux souhaitent partager plus facilement certains résultats entre services. Le professeur Duval, vous y êtes favorable.\nUne analyse répétée inutilement retarde le traitement. Un accès sécurisé, limité aux professionnels concernés, pourrait l'éviter.\nMadame Leclerc, vous n'êtes pas convaincue.\nJe soutiens la coordination, mais le patient doit comprendre qui consulte ses données et pouvoir signaler un accès injustifié. Un système pratique pour les soignants ne suffit pas s'il reste opaque pour les personnes concernées.\nJe suis d'accord sur la transparence, mais elle ne devrait pas bloquer un échange nécessaire aux soins.\nSur quoi porte essentiellement le désaccord ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Les hôpitaux souhaitent partager plus facilement certains résultats entre services. Le professeur Duval, vous y êtes favorable.","speaker":"female"},{"voice":"male","text":"Une analyse répétée inutilement retarde le traitement. Un accès sécurisé, limité aux professionnels concernés, pourrait l'éviter.","speaker":"male"},{"voice":"female","text":"Madame Leclerc, vous n'êtes pas convaincue.","speaker":"female"},{"voice":"female","text":"Je soutiens la coordination, mais le patient doit comprendre qui consulte ses données et pouvoir signaler un accès injustifié. Un système pratique pour les soignants ne suffit pas s'il reste opaque pour les personnes concernées.","speaker":"female_alt"},{"voice":"male","text":"Je suis d'accord sur la transparence, mais elle ne devrait pas bloquer un échange nécessaire aux soins.","speaker":"male"},{"voice":"female","text":"Sur quoi porte essentiellement le désaccord ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":44.669,"slotSeconds":69},{"number":30,"kind":"interview","question":"Quelle idée l'intervenante défend-elle à propos de l'aide aux proches ?","options":["Réserver l'accompagnement aux familles qui gèrent déjà les soins.","Confier progressivement les soins aux proches les plus disponibles.","Alléger la charge des aidants avec des services et du répit.","Former les proches à remplacer les interventions professionnelles."],"correct":"C","explanation":"L'intervenante veut soutenir les aidants sans augmenter leur charge.","transcript":"Question 30.\nVotre association soutient les personnes qui accompagnent un parent dépendant. Faut-il les former à effectuer davantage de soins ?\nCertaines formations sont utiles, mais il faut éviter de transformer les proches en professionnels à temps plein. Beaucoup travaillent, élèvent leurs enfants et éprouvent déjà une grande fatigue. Notre priorité est de proposer des moments de répit, des renseignements fiables et une orientation vers des services adaptés. Aider une famille, ce n'est pas lui demander de tout faire seule sous prétexte qu'elle connaît bien le malade.\nQuelle idée l'intervenante défend-elle à propos de l'aide aux proches ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre association soutient les personnes qui accompagnent un parent dépendant. Faut-il les former à effectuer davantage de soins ?"},{"voice":"female","text":"Certaines formations sont utiles, mais il faut éviter de transformer les proches en professionnels à temps plein. Beaucoup travaillent, élèvent leurs enfants et éprouvent déjà une grande fatigue. Notre priorité est de proposer des moments de répit, des renseignements fiables et une orientation vers des services adaptés. Aider une famille, ce n'est pas lui demander de tout faire seule sous prétexte qu'elle connaît bien le malade."},{"voice":"female","text":"Quelle idée l'intervenante défend-elle à propos de l'aide aux proches ?"}],"audio":"q-30.mp3","audioSeconds":37.002,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle conclusion méthodologique la conférencière souligne-t-elle ?","options":["Attribuer la baisse au centre, puisqu'elle suit son ouverture.","Examiner d'autres facteurs avant d'établir un lien de cause.","Comparer uniquement les admissions des mêmes mois successifs.","Privilégier les avis des médecins à l'analyse des tendances."],"correct":"B","explanation":"La conférencière demande de contrôler les autres facteurs intervenus simultanément.","transcript":"Question 31.\nDans une ville, les hospitalisations pour troubles respiratoires ont diminué après l'ouverture d'un centre de dépistage. Ce résultat semble encourageant, mais il ne démontre pas, à lui seul, que le dépistage en est la cause. La pollution était également moins importante cette année-là et plusieurs professionnels ont changé leurs pratiques. Pour évaluer l'effet propre du centre, nous devons disposer d'une comparaison pertinente, tenir compte de ces évolutions parallèles et examiner les données sur une durée suffisante. Une succession temporelle n'est pas une preuve de causalité.\nQuelle conclusion méthodologique la conférencière souligne-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Dans une ville, les hospitalisations pour troubles respiratoires ont diminué après l'ouverture d'un centre de dépistage. Ce résultat semble encourageant, mais il ne démontre pas, à lui seul, que le dépistage en est la cause. La pollution était également moins importante cette année-là et plusieurs professionnels ont changé leurs pratiques. Pour évaluer l'effet propre du centre, nous devons disposer d'une comparaison pertinente, tenir compte de ces évolutions parallèles et examiner les données sur une durée suffisante. Une succession temporelle n'est pas une preuve de causalité."},{"voice":"female","text":"Quelle conclusion méthodologique la conférencière souligne-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":39.062,"slotSeconds":75},{"number":32,"kind":"interview","question":"Comment le spécialiste propose-t-il d'utiliser les prévisions hospitalières ?","options":["Confier au modèle l'ajustement quotidien des effectifs.","Réviser les projections selon les admissions observées.","Maintenir l'estimation initiale pour comparer les services.","Donner à la direction une valeur certaine à respecter."],"correct":"B","explanation":"Le spécialiste souhaite réviser les scénarios à partir des données réelles.","transcript":"Question 32.\nVotre équipe prévoit l'occupation des lits à partir des admissions passées. Peut-on fixer définitivement les effectifs sur cette base ?\nNon. Le modèle nous aide à prévoir des fourchettes, mais il ne connaît ni toutes les épidémies futures ni les absences imprévues du personnel. Nous comparons ses estimations aux admissions réelles chaque semaine et nous ajustons les scénarios. Le danger serait de présenter une valeur précise comme une promesse. L'outil doit appuyer une décision humaine, notamment lorsque les services sont sous tension.\nComment le spécialiste propose-t-il d'utiliser les prévisions hospitalières ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"female","text":"Votre équipe prévoit l'occupation des lits à partir des admissions passées. Peut-on fixer définitivement les effectifs sur cette base ?"},{"voice":"male","text":"Non. Le modèle nous aide à prévoir des fourchettes, mais il ne connaît ni toutes les épidémies futures ni les absences imprévues du personnel. Nous comparons ses estimations aux admissions réelles chaque semaine et nous ajustons les scénarios. Le danger serait de présenter une valeur précise comme une promesse. L'outil doit appuyer une décision humaine, notamment lorsque les services sont sous tension."},{"voice":"female","text":"Comment le spécialiste propose-t-il d'utiliser les prévisions hospitalières ?"}],"audio":"q-32.mp3","audioSeconds":39.417,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle réserve la chroniqueuse formule-t-elle sur les délais publiés ?","options":["Le délai moyen varie uniquement entre les spécialités.","Le délai moyen surestime surtout les demandes urgentes.","Le délai moyen masque de grandes différences entre patients.","Le délai moyen reste fiable lorsque les patients sont nombreux."],"correct":"C","explanation":"L'indicateur agrégé cache des écarts importants entre patients.","transcript":"Question 33.\nLe nouvel indicateur municipal annonce un délai moyen de huit jours pour consulter un spécialiste. C'est une information intéressante, mais elle ne nous dit pas ce que vivent tous les patients. Si certaines personnes obtiennent une place sous deux jours et d'autres attendent deux mois, la moyenne peut donner une impression trompeuse. Il serait utile de publier aussi la proportion de patients vus dans un délai raisonnable, les différences entre spécialités et les situations d'urgence. Le problème n'est pas le chiffre en lui-même, mais ce qu'on lui fait raconter.\nQuelle réserve la chroniqueuse formule-t-elle sur les délais publiés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Le nouvel indicateur municipal annonce un délai moyen de huit jours pour consulter un spécialiste. C'est une information intéressante, mais elle ne nous dit pas ce que vivent tous les patients. Si certaines personnes obtiennent une place sous deux jours et d'autres attendent deux mois, la moyenne peut donner une impression trompeuse. Il serait utile de publier aussi la proportion de patients vus dans un délai raisonnable, les différences entre spécialités et les situations d'urgence. Le problème n'est pas le chiffre en lui-même, mais ce qu'on lui fait raconter."},{"voice":"female","text":"Quelle réserve la chroniqueuse formule-t-elle sur les délais publiés ?"}],"audio":"q-33.mp3","audioSeconds":36.417,"slotSeconds":67},{"number":34,"kind":"roundtable","question":"Quelle solution commune se dessine au cours de la discussion ?","options":["Créer des permanences identiques dans chaque commune dès l'ouverture.","Réserver le premier entretien aux équipes médicales spécialisées.","Tester un premier accueil discret qui oriente vers les professionnels.","Utiliser une ligne automatisée avant toute intervention humaine."],"correct":"C","explanation":"Ils convergent vers un accueil de liaison, confidentiel et orientant.","transcript":"Question 34.\nNous parlons de l'accès aux consultations psychologiques dans les petites communes.\nNos permanences sont presque pleines. Ouvrir davantage de créneaux demande des professionnels que nous ne trouvons pas.\nJe représente les associations de jeunes. Beaucoup hésitent à demander de l'aide s'ils doivent expliquer leur situation à plusieurs guichets.\nNous pourrions désigner une personne de liaison formée, capable de proposer un premier entretien et d'orienter rapidement vers le bon service.\nÀ condition que les échanges restent confidentiels et que cette personne ne prétende pas établir un diagnostic.\nD'accord. Nous testerons l'accueil dans deux communes avant de l'étendre.\nQuelle solution commune se dessine au cours de la discussion ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Nous parlons de l'accès aux consultations psychologiques dans les petites communes.","speaker":"female"},{"voice":"male","text":"Nos permanences sont presque pleines. Ouvrir davantage de créneaux demande des professionnels que nous ne trouvons pas.","speaker":"male"},{"voice":"female","text":"Je représente les associations de jeunes. Beaucoup hésitent à demander de l'aide s'ils doivent expliquer leur situation à plusieurs guichets.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions désigner une personne de liaison formée, capable de proposer un premier entretien et d'orienter rapidement vers le bon service.","speaker":"male"},{"voice":"female","text":"À condition que les échanges restent confidentiels et que cette personne ne prétende pas établir un diagnostic.","speaker":"female_alt"},{"voice":"male","text":"D'accord. Nous testerons l'accueil dans deux communes avant de l'étendre.","speaker":"male"},{"voice":"female","text":"Quelle solution commune se dessine au cours de la discussion ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":46.89,"slotSeconds":69},{"number":35,"kind":"interview","question":"Quelle limite l'ingénieure attribue-t-elle aux montres de santé ?","options":["Les données sont exploitables uniquement après une consultation.","Les alertes sont fiables seulement avec un bracelet coûteux.","Les signaux doivent être interprétés avec un contexte médical.","Les montres détectent systématiquement tout problème cardiaque."],"correct":"C","explanation":"Les alertes demandent interprétation clinique plutôt qu'une lecture comme diagnostic.","transcript":"Question 35.\nCes montres peuvent détecter des variations du rythme cardiaque. Pourquoi certains médecins restent-ils prudents ?\nElles fournissent des informations utiles sur la durée, mais les capteurs peuvent être perturbés par le mouvement ou par un bracelet mal ajusté. Une alerte n'est pas, à elle seule, un diagnostic, et son absence ne garantit pas qu'aucun problème n'existe. Nous conseillons de partager les données avec un professionnel lorsqu'une inquiétude persiste, plutôt que de réagir à chaque notification comme à une certitude.\nQuelle limite l'ingénieure attribue-t-elle aux montres de santé ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Ces montres peuvent détecter des variations du rythme cardiaque. Pourquoi certains médecins restent-ils prudents ?"},{"voice":"female","text":"Elles fournissent des informations utiles sur la durée, mais les capteurs peuvent être perturbés par le mouvement ou par un bracelet mal ajusté. Une alerte n'est pas, à elle seule, un diagnostic, et son absence ne garantit pas qu'aucun problème n'existe. Nous conseillons de partager les données avec un professionnel lorsqu'une inquiétude persiste, plutôt que de réagir à chaque notification comme à une certitude."},{"voice":"female","text":"Quelle limite l'ingénieure attribue-t-elle aux montres de santé ?"}],"audio":"q-35.mp3","audioSeconds":36.015,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition la décision du patient est-elle réellement respectée ?","options":["Lorsque le patient saisit les choix et peut décider librement.","Lorsque la famille confirme avoir compris les recommandations.","Lorsque le formulaire contient les signatures requises.","Lorsque le médecin a détaillé le traitement retenu."],"correct":"A","explanation":"Le consentement exige compréhension et liberté de décision.","transcript":"Question 36.\nVous travaillez sur le consentement aux soins. Suffit-il de faire signer un formulaire ?\nLa signature peut attester qu'une information a été remise, mais elle ne garantit pas que la personne l'a comprise ou qu'elle a pu poser des questions. Certains patients ont besoin d'un interprète, d'un délai de réflexion ou d'une explication moins technique. Ils doivent également pouvoir refuser sans se sentir punis. Notre rôle n'est pas de convaincre à tout prix, mais de permettre une décision éclairée dans les limites de la situation médicale.\nÀ quelle condition la décision du patient est-elle réellement respectée ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Vous travaillez sur le consentement aux soins. Suffit-il de faire signer un formulaire ?"},{"voice":"female","text":"La signature peut attester qu'une information a été remise, mais elle ne garantit pas que la personne l'a comprise ou qu'elle a pu poser des questions. Certains patients ont besoin d'un interprète, d'un délai de réflexion ou d'une explication moins technique. Ils doivent également pouvoir refuser sans se sentir punis. Notre rôle n'est pas de convaincre à tout prix, mais de permettre une décision éclairée dans les limites de la situation médicale."},{"voice":"female","text":"À quelle condition la décision du patient est-elle réellement respectée ?"}],"audio":"q-36.mp3","audioSeconds":36.433,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse présente-t-elle plusieurs récits du même programme ?","options":["Pour écarter les chiffres administratifs en faveur des témoignages.","Pour distinguer des expériences selon les situations vécues.","Pour retenir principalement les témoignages les plus fréquents.","Pour montrer que les points de vue sont tous exacts sur les faits."],"correct":"B","explanation":"La chercheuse confronte les vécus divergents aux faits et contextes.","transcript":"Question 37.\nVotre étude sur les visites à domicile contient des avis très opposés. Comment pouvez-vous en tirer une conclusion ?\nNous vérifions d'abord les faits : nombre de visites, changements de planning, coûts réels. Ensuite, nous situons les expériences. Une personne vivant seule peut apprécier une visite qui rassure; un proche aidant peut juger que cette même visite ne répond pas à ses besoins. Supprimer ces contradictions reviendrait à masquer la diversité du public. Il faut les expliquer et déterminer quelles conditions produisent chaque expérience, sans prétendre que tous les témoignages sont également exacts sur chaque fait.\nPourquoi la chercheuse présente-t-elle plusieurs récits du même programme ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Votre étude sur les visites à domicile contient des avis très opposés. Comment pouvez-vous en tirer une conclusion ?"},{"voice":"female","text":"Nous vérifions d'abord les faits : nombre de visites, changements de planning, coûts réels. Ensuite, nous situons les expériences. Une personne vivant seule peut apprécier une visite qui rassure; un proche aidant peut juger que cette même visite ne répond pas à ses besoins. Supprimer ces contradictions reviendrait à masquer la diversité du public. Il faut les expliquer et déterminer quelles conditions produisent chaque expérience, sans prétendre que tous les témoignages sont également exacts sur chaque fait."},{"voice":"female","text":"Pourquoi la chercheuse présente-t-elle plusieurs récits du même programme ?"}],"audio":"q-37.mp3","audioSeconds":43.335,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'oratrice décrit-elle ?","options":["L'information sur le risque peut remplacer l'accès aux services.","Une campagne réussie peut dépasser les capacités de suivi.","La visibilité d'une campagne dépend surtout de son financement.","La prévention réduit le nombre de demandes de suivi médical."],"correct":"B","explanation":"Le succès de sensibilisation crée une demande que les structures peuvent ne pas satisfaire.","transcript":"Question 38.\nUne campagne de prévention réussie peut provoquer davantage de demandes d'examens que le système local n'est capable d'en absorber. C'est le paradoxe que nous observons dans plusieurs villes. Informer les habitants est essentiel, mais s'ils découvrent un risque sans pouvoir accéder rapidement au suivi annoncé, l'inquiétude peut augmenter et la confiance diminuer. Les responsables ne devraient donc pas évaluer leur campagne seulement au nombre de personnes sensibilisées. Ils doivent anticiper les consultations, former les équipes et vérifier si les personnes les plus vulnérables obtiennent réellement une prise en charge. Un message efficace n'a de valeur durable que si les services peuvent répondre à la demande qu'il crée.\nQuel paradoxe l'oratrice décrit-elle ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Une campagne de prévention réussie peut provoquer davantage de demandes d'examens que le système local n'est capable d'en absorber. C'est le paradoxe que nous observons dans plusieurs villes. Informer les habitants est essentiel, mais s'ils découvrent un risque sans pouvoir accéder rapidement au suivi annoncé, l'inquiétude peut augmenter et la confiance diminuer. Les responsables ne devraient donc pas évaluer leur campagne seulement au nombre de personnes sensibilisées. Ils doivent anticiper les consultations, former les équipes et vérifier si les personnes les plus vulnérables obtiennent réellement une prise en charge. Un message efficace n'a de valeur durable que si les services peuvent répondre à la demande qu'il crée."},{"voice":"female","text":"Quel paradoxe l'oratrice décrit-elle ?"}],"audio":"q-38.mp3","audioSeconds":45.612,"slotSeconds":80},{"number":39,"kind":"interview","question":"Quelle condition la responsable juge-t-elle essentielle à la pérennité du service ?","options":["Étendre les tournées avant de recruter du personnel supplémentaire.","Réduire chaque rendez-vous pour multiplier les destinations.","Financer le service et prévoir le suivi avant de l'élargir.","Choisir les villages selon l'affluence des premiers mois."],"correct":"C","explanation":"La responsable veut sécuriser moyens et continuité avant d'étendre le dispositif.","transcript":"Question 39.\nLe cabinet mobile a été très fréquenté durant son premier trimestre. Pourquoi ne pas multiplier immédiatement les tournées ?\nParce que les premiers mois reposaient sur du matériel prêté et des heures supplémentaires exceptionnelles. Avant d'ajouter des destinations, nous devons savoir qui financera les remplacements, comment les dossiers seront suivis entre deux passages et où orienter les patients qui ont besoin d'un examen. Nous devons aussi recueillir l'avis des villages qui n'ont pas bénéficié du premier itinéraire. Une forte fréquentation démontre un besoin; elle ne garantit pas que nous pouvons maintenir la qualité des soins partout.\nQuelle condition la responsable juge-t-elle essentielle à la pérennité du service ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Le cabinet mobile a été très fréquenté durant son premier trimestre. Pourquoi ne pas multiplier immédiatement les tournées ?"},{"voice":"female","text":"Parce que les premiers mois reposaient sur du matériel prêté et des heures supplémentaires exceptionnelles. Avant d'ajouter des destinations, nous devons savoir qui financera les remplacements, comment les dossiers seront suivis entre deux passages et où orienter les patients qui ont besoin d'un examen. Nous devons aussi recueillir l'avis des villages qui n'ont pas bénéficié du premier itinéraire. Une forte fréquentation démontre un besoin; elle ne garantit pas que nous pouvons maintenir la qualité des soins partout."},{"voice":"female","text":"Quelle condition la responsable juge-t-elle essentielle à la pérennité du service ?"}],"audio":"q-39.mp3","audioSeconds":41.234,"slotSeconds":82}]},{"id":"tcf-listening-04","version":"tcf-listening-2026-11-test04-v3","title":"TCF Listening · Test 04","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Une employée trie les ouvrages rendus sur un chariot près du comptoir.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. La bibliothécaire range des ouvrages sur un chariot. B. La bibliothécaire emprunte un livre à une étudiante. C. L'étudiante dépose des journaux devant la porte. D. L'étudiante cherche une place dans une salle de cours.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. La bibliothécaire range des ouvrages sur un chariot. B. La bibliothécaire emprunte un livre à une étudiante. C. L'étudiante dépose des journaux devant la porte. D. L'étudiante cherche une place dans une salle de cours."}],"audio":"q-01.mp3","audioSeconds":20.706,"slotSeconds":33,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'enseignant indique une grille d'horaires affichée au tableau de la classe.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Les élèves installent du matériel dans une salle vide. B. Le professeur présente l'emploi du temps au tableau. C. Le professeur corrige des devoirs à son bureau. D. Les élèves passent une épreuve écrite sans professeur.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Les élèves installent du matériel dans une salle vide. B. Le professeur présente l'emploi du temps au tableau. C. Le professeur corrige des devoirs à son bureau. D. Les élèves passent une épreuve écrite sans professeur."}],"audio":"q-02.mp3","audioSeconds":20.683,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'étudiante utilise son téléphone devant un lecteur de contrôle à l'entrée.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. L'élève vérifie une note sur le tableau d'affichage. B. L'élève remplit une fiche à la réception. C. L'élève achète un ticket auprès du concierge. D. L'élève présente un code pour accéder au bâtiment.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'élève vérifie une note sur le tableau d'affichage. B. L'élève remplit une fiche à la réception. C. L'élève achète un ticket auprès du concierge. D. L'élève présente un code pour accéder au bâtiment."}],"audio":"q-03.mp3","audioSeconds":19.94,"slotSeconds":35,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'enfant rend un livre en présence d'un adulte au comptoir de la médiathèque.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Un parent lit un conte au groupe d'enfants. B. Une enseignante écrit sur un tableau avec un enfant. C. Un enfant remet un livre au guichet avec un parent. D. Un enfant choisit un livre sur une étagère.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Un parent lit un conte au groupe d'enfants. B. Une enseignante écrit sur un tableau avec un enfant. C. Un enfant remet un livre au guichet avec un parent. D. Un enfant choisit un livre sur une étagère."}],"audio":"q-04.mp3","audioSeconds":19.594,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse correcte indique la salle deux et son emplacement après l'escalier. Les autres propositions donnent une fréquence, des intervenantes ou une durée.","transcript":"Question 5.\nLe cours de conversation a lieu dans quelle salle ?\nA. Depuis deux semaines, tous les mercredis. B. Dans la salle deux, juste après l'escalier. C. Pendant deux heures, après le déjeuner. D. Avec deux intervenantes, dont une invitée.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Le cours de conversation a lieu dans quelle salle ?"},{"voice":"male","text":"A. Depuis deux semaines, tous les mercredis. B. Dans la salle deux, juste après l'escalier. C. Pendant deux heures, après le déjeuner. D. Avec deux intervenantes, dont une invitée."}],"audio":"q-05.mp3","audioSeconds":19.598,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'envoi d'un lien de récupération répond à la perte d'identifiant.","transcript":"Question 6.\nJ'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?\nA. Vous pourrez obtenir des résultats en fin de séance. B. Les exercices restent ouverts toute la semaine. C. Je vais vous envoyer un lien de récupération. D. Les cours commencent demain à la même heure.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"J'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?"},{"voice":"female","text":"A. Vous pourrez obtenir des résultats en fin de séance. B. Les exercices restent ouverts toute la semaine. C. Je vais vous envoyer un lien de récupération. D. Les cours commencent demain à la même heure."}],"audio":"q-06.mp3","audioSeconds":21.664,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse correcte confirme l'inscription obligatoire et précise qu'il faut réserver une place en ligne.","transcript":"Question 7.\nEst-ce que l'atelier de demain demande une inscription ?\nA. L'atelier se déroule près de la gare. B. Oui, les enseignants y participent aussi. C. L'atelier commencera à seize heures. D. Oui, il faut réserver une place en ligne.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Est-ce que l'atelier de demain demande une inscription ?"},{"voice":"male","text":"A. L'atelier se déroule près de la gare. B. Oui, les enseignants y participent aussi. C. L'atelier commencera à seize heures. D. Oui, il faut réserver une place en ligne."}],"audio":"q-07.mp3","audioSeconds":19.586,"slotSeconds":32},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse correcte refuse le prêt à domicile : cet exemplaire doit être consulté sur place à la bibliothèque.","transcript":"Question 8.\nPuis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?\nA. Non, cet exemplaire doit rester sur place. B. Ce dictionnaire a été publié récemment. C. Ce dictionnaire se trouve au premier étage. D. Ce dictionnaire existe en version numérique.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Puis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?"},{"voice":"female","text":"A. Non, cet exemplaire doit rester sur place. B. Ce dictionnaire a été publié récemment. C. Ce dictionnaire se trouve au premier étage. D. Ce dictionnaire existe en version numérique."}],"audio":"q-08.mp3","audioSeconds":19.377,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Où les étudiants suivront-ils le cours de demain ?","options":["Dans la salle dix-huit, demain à neuf heures.","Au laboratoire trois, demain à neuf heures.","Au laboratoire trois, demain à dix heures.","Dans la salle dix-huit, demain à dix heures."],"correct":"B","explanation":"La séance est déplacée au laboratoire trois, tandis que l'horaire de neuf heures est maintenu. L'annonce dit « demain » sans préciser le jour de la semaine.","transcript":"Question 9.\nLe cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs.\nOù les étudiants suivront-ils le cours de demain ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Le cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs."},{"voice":"female","text":"Où les étudiants suivront-ils le cours de demain ?"}],"audio":"q-09.mp3","audioSeconds":19.662,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?","options":["Les documents de candidature ont été envoyés trop tard.","Le candidat doit fournir l'accord de son établissement.","La session ne dispose plus d'aucune place disponible.","Le candidat doit repasser un test de langue préalable."],"correct":"B","explanation":"La participation attend une autorisation officielle malgré un dossier complet.","transcript":"Question 10.\nJ'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants.\nVotre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise.\nJe peux vous l'apporter demain.\nOui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription.\nPourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"J'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants."},{"voice":"female","text":"Votre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise."},{"voice":"male","text":"Je peux vous l'apporter demain."},{"voice":"female","text":"Oui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription."},{"voice":"female","text":"Pourquoi l'étudiant ne peut-il pas rejoindre immédiatement le groupe ?"}],"audio":"q-10.mp3","audioSeconds":26.212,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Comment doit-on proposer un sujet pour l'échange linguistique ?","options":["En écrivant au responsable avant vendredi.","En proposant son sujet à l'ouverture vendredi.","En appelant l'équipe de langues avant mercredi.","En utilisant le formulaire du site avant mercredi."],"correct":"D","explanation":"Les thèmes doivent être transmis par formulaire en ligne avant mercredi midi.","transcript":"Question 11.\nLe club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire.\nComment doit-on proposer un sujet pour l'échange linguistique ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Le club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire."},{"voice":"female","text":"Comment doit-on proposer un sujet pour l'échange linguistique ?"}],"audio":"q-11.mp3","audioSeconds":25.513,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quel changement la tutrice propose-t-elle ?","options":["Prévoir le tutorat vendredi dans une salle disponible.","Conserver le mardi et changer uniquement la salle.","Déplacer le tutorat au mercredi près du secrétariat.","Faire le tutorat jeudi dans un autre bâtiment."],"correct":"A","explanation":"Ils choisissent le vendredi dans une salle près du secrétariat.","transcript":"Question 12.\nJe peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi.\nJ'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?\nLe vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat.\nParfait. Je vais prévenir la personne qui coordonne les séances.\nQuel changement la tutrice propose-t-elle ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Je peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi."},{"voice":"male","text":"J'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?"},{"voice":"female","text":"Le vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat."},{"voice":"male","text":"Parfait. Je vais prévenir la personne qui coordonne les séances."},{"voice":"female","text":"Quel changement la tutrice propose-t-elle ?"}],"audio":"q-12.mp3","audioSeconds":25.004,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quelle activité sera interrompue mardi ?","options":["Les expériences des élèves de troisième en laboratoire.","Les vérifications électriques du laboratoire mardi.","Les activités des enseignants prévues mercredi en sciences.","Les ateliers de lecture prévus mardi en bibliothèque."],"correct":"A","explanation":"Le laboratoire ferme aux classes mardi. Les expériences du groupe de troisième sont donc reportées à jeudi. La bibliothèque reste ouverte et la vérification électrique a bien lieu.","transcript":"Question 13.\nLe laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi.\nQuelle activité sera interrompue mardi ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi."},{"voice":"female","text":"Quelle activité sera interrompue mardi ?"}],"audio":"q-13.mp3","audioSeconds":21.717,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution le professeur retient-il pour la séance ?","options":["Maintenir la séance en retardant le début pour tous.","Répartir les étudiants dans deux salles sans ordinateur.","Former deux groupes qui utilisent la salle à tour de rôle.","Faire l'écoute ensemble dans une salle non équipée."],"correct":"C","explanation":"Ils utiliseront la petite salle en deux groupes, avec une autre tâche pour l'attente.","transcript":"Question 14.\nLe haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes.\nLe laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs.\nNous avons douze étudiants.\nOn pourrait les répartir en deux groupes et faire l'activité l'un après l'autre.\nD'accord, je prépare une tâche de lecture pour ceux qui attendent.\nQuelle solution le professeur retient-il pour la séance ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes."},{"voice":"female","text":"Le laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs."},{"voice":"male","text":"Nous avons douze étudiants."},{"voice":"female","text":"On pourrait les répartir en deux groupes et faire l'activité l'un après l'autre."},{"voice":"male","text":"D'accord, je prépare une tâche de lecture pour ceux qui attendent."},{"voice":"female","text":"Quelle solution le professeur retient-il pour la séance ?"}],"audio":"q-14.mp3","audioSeconds":29.614,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Quelle difficulté accompagne le lancement des cours du soir ?","options":["Les cours proposés ne correspondent pas aux demandes.","La formation du soir coûte trop cher aux salariés.","Les trajets après les cours sont parfois difficiles.","Les professeurs ne peuvent assurer les cours tardifs."],"correct":"C","explanation":"La demande existe, mais l'accès au transport en fin de soirée demeure compliqué.","transcript":"Question 15.\nÀ Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier.\nQuelle difficulté accompagne le lancement des cours du soir ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"À Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier."},{"voice":"female","text":"Quelle difficulté accompagne le lancement des cours du soir ?"}],"audio":"q-15.mp3","audioSeconds":28.88,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les enseignants échangent-ils leurs créneaux ?","options":["Un jury a besoin de l'un des professeurs jeudi.","Les élèves doivent refaire une partie des examens.","Un cours doit être déplacé pour préparer une salle.","Un groupe souhaite changer d'enseignant mardi."],"correct":"A","explanation":"Un enseignant doit remplacer un collègue dans un jury d'examen jeudi.","transcript":"Question 16.\nJe peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues.\nMerci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là.\nOn intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi.\nJe préviendrai les étudiants, les salles ne changent pas.\nPourquoi les enseignants échangent-ils leurs créneaux ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Je peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues."},{"voice":"male","text":"Merci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là."},{"voice":"female","text":"On intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi."},{"voice":"male","text":"Je préviendrai les étudiants, les salles ne changent pas."},{"voice":"female","text":"Pourquoi les enseignants échangent-ils leurs créneaux ?"}],"audio":"q-16.mp3","audioSeconds":25.945,"slotSeconds":41},{"number":17,"kind":"announcement","question":"Que faut-il présenter pour créer une carte de bibliothèque ?","options":["Une pièce d'identité et un justificatif d'adresse.","Une carte scolaire et un document de l'école.","Une pièce d'identité et une photographie récente.","Une carte d'étudiant et un justificatif de domicile."],"correct":"A","explanation":"Les deux documents requis sont l'identité et le justificatif d'adresse.","transcript":"Question 17.\nLa médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement.\nQue faut-il présenter pour créer une carte de bibliothèque ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement."},{"voice":"female","text":"Que faut-il présenter pour créer une carte de bibliothèque ?"}],"audio":"q-17.mp3","audioSeconds":25.583,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne préfère-t-elle une autre formation ?","options":["Elle préfère une session avec davantage de participants.","Elle souhaite une session compatible avec son travail.","Elle cherche à suivre la formation plus rapidement.","Elle veut un cours qui limite les exercices pratiques."],"correct":"B","explanation":"Son travail l'empêche d'assister au programme en semaine.","transcript":"Question 18.\nBonjour, je m'intéresse à votre formation informatique de vingt heures.\nElle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures.\nJe travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis.\nOui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe.\nDans ce cas, inscrivez-moi à celle du samedi, s'il reste une place.\nPourquoi la personne préfère-t-elle une autre formation ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Bonjour, je m'intéresse à votre formation informatique de vingt heures."},{"voice":"male","text":"Elle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures."},{"voice":"female","text":"Je travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis."},{"voice":"male","text":"Oui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe."},{"voice":"female","text":"Dans ce cas, inscrivez-moi à celle du samedi, s'il reste une place."},{"voice":"female","text":"Pourquoi la personne préfère-t-elle une autre formation ?"}],"audio":"q-18.mp3","audioSeconds":32.122,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi les ateliers de lecture ont-ils moins de places ?","options":["Pour accorder davantage de temps aux enfants débutants.","Pour permettre des exercices plus longs aux grands lecteurs.","Pour donner plus de place aux parents dans la salle.","Pour réserver des séances aux enfants déjà inscrits."],"correct":"A","explanation":"L'effectif réduit permet un meilleur accompagnement individuel.","transcript":"Question 19.\nPendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles.\nPourquoi les ateliers de lecture ont-ils moins de places ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles."},{"voice":"female","text":"Pourquoi les ateliers de lecture ont-ils moins de places ?"}],"audio":"q-19.mp3","audioSeconds":24.259,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Qu'est-ce qui préoccupe surtout l'apprenant ?","options":["Il doit partager les exercices avec les autres élèves.","Il ne dispose pas d'équipement adapté à domicile.","Il ne peut pas joindre son professeur après les cours.","Il juge trop difficile le contenu des devoirs numériques."],"correct":"B","explanation":"L'apprenant dispose d'un seul téléphone partagé et n'a pas d'ordinateur.","transcript":"Question 20.\nJ'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon.\nVotre connexion fonctionne-t-elle normalement ?\nPas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi.\nJe peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous.\nCela m'aiderait à travailler régulièrement.\nQu'est-ce qui préoccupe surtout l'apprenant ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"J'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon."},{"voice":"female","text":"Votre connexion fonctionne-t-elle normalement ?"},{"voice":"male","text":"Pas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi."},{"voice":"female","text":"Je peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous."},{"voice":"male","text":"Cela m'aiderait à travailler régulièrement."},{"voice":"female","text":"Qu'est-ce qui préoccupe surtout l'apprenant ?"}],"audio":"q-20.mp3","audioSeconds":28.755,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","options":["Pour couvrir les séances où il manque des tuteurs.","Pour assurer les ateliers avec les mêmes bénévoles.","Pour remplacer tous les ateliers du mercredi.","Pour sélectionner les lecteurs les plus avancés."],"correct":"A","explanation":"La confirmation permet de renforcer les séances du vendredi où le personnel manque.","transcript":"Question 21.\nL'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation.\nPourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"L'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation."},{"voice":"female","text":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?"}],"audio":"q-21.mp3","audioSeconds":27.463,"slotSeconds":54},{"number":22,"kind":"interview","question":"Quel aspect la formatrice considère-t-elle comme le plus important ?","options":["Les exercices sont raccourcis pour les nouveaux inscrits.","Les cours donnent directement accès à un diplôme.","L'entraide permet aux apprenants de reprendre confiance.","La formation supprime les évaluations en groupe."],"correct":"C","explanation":"Elle met en avant la confiance acquise grâce au groupe.","transcript":"Question 22.\nVotre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?\nCertains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants.\nQuel aspect la formatrice considère-t-elle comme le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Votre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?"},{"voice":"female","text":"Certains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants."},{"voice":"female","text":"Quel aspect la formatrice considère-t-elle comme le plus important ?"}],"audio":"q-22.mp3","audioSeconds":36.282,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Quel compromis ressort de la discussion sur les devoirs ?","options":["Supprimer les devoirs et déplacer le soutien aux familles.","Allonger les exercices et créer une permanence obligatoire.","Conserver les devoirs mais proposer davantage de corrections.","Réduire les devoirs en maintenant un temps d'aide à l'école."],"correct":"D","explanation":"Les participants retiennent des révisions brèves et une aide accessible sans surcharger les familles.","transcript":"Question 23.\nUne représentante de parents estime que les devoirs écrits prennent trop de temps aux familles.\nComme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions.\nLes enfants n'ont pas tous un adulte disponible pour les accompagner.\nNous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème.\nSi les consignes sont claires et que la charge est limitée, ce serait un progrès.\nÉvaluons cette formule pendant un trimestre.\nQuel compromis ressort de la discussion sur les devoirs ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Une représentante de parents estime que les devoirs écrits prennent trop de temps aux familles.","speaker":"female"},{"voice":"male","text":"Comme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions.","speaker":"male"},{"voice":"female","text":"Les enfants n'ont pas tous un adulte disponible pour les accompagner.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème.","speaker":"male"},{"voice":"female","text":"Si les consignes sont claires et que la charge est limitée, ce serait un progrès.","speaker":"female_alt"},{"voice":"male","text":"Évaluons cette formule pendant un trimestre.","speaker":"male"},{"voice":"female","text":"Quel compromis ressort de la discussion sur les devoirs ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":39.105,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle faiblesse de l'enquête la chercheuse souligne-t-elle ?","options":["L'enquête mesure uniquement les progrès sans satisfaction.","L'enquête interroge surtout ceux ayant échoué aux examens.","L'enquête porte seulement sur des adultes plutôt que des jeunes.","L'enquête laisse de côté les personnes ayant interrompu le cours."],"correct":"D","explanation":"L'étude ignore les personnes qui se sont arrêtées avant la fin.","transcript":"Question 24.\nVous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?\nNon, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits.\nQuelle faiblesse de l'enquête la chercheuse souligne-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Vous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?"},{"voice":"female","text":"Non, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits."},{"voice":"female","text":"Quelle faiblesse de l'enquête la chercheuse souligne-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":38.099,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quel obstacle le reportage met-il en évidence ?","options":["Les enseignants ont besoin d'un accompagnement informatique.","Les élèves reçoivent des appareils de qualité très différente.","Les familles ont un accès inégal à Internet à la maison.","Les classes disposent de connexions trop lentes le matin."],"correct":"C","explanation":"L'accès numérique à la maison est inégal, ce qui rend les devoirs difficiles pour certains.","transcript":"Question 25.\nDans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux.\nMais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous.\nL'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils.\nQuel obstacle le reportage met-il en évidence ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux."},{"voice":"male","text":"Mais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous."},{"voice":"female","text":"L'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils."},{"voice":"female","text":"Quel obstacle le reportage met-il en évidence ?"}],"audio":"q-25.mp3","audioSeconds":36.114,"slotSeconds":71},{"number":26,"kind":"interview","question":"Pourquoi le responsable insiste-t-il sur le suivi des apprentis ?","options":["L'absence de diplôme prouve qu'un apprentissage a échoué.","La progression professionnelle dépend uniquement du diplôme.","La certification doit toujours primer sur les conditions de travail.","Le diplôme ne suffit pas à évaluer la qualité du parcours."],"correct":"D","explanation":"Il considère l'accompagnement et les conditions de formation, pas uniquement le diplôme.","transcript":"Question 26.\nVotre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?\nLe diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile.\nPourquoi le responsable insiste-t-il sur le suivi des apprentis ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Votre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?"},{"voice":"male","text":"Le diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile."},{"voice":"female","text":"Pourquoi le responsable insiste-t-il sur le suivi des apprentis ?"}],"audio":"q-26.mp3","audioSeconds":39.26,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Comment les deux enseignants réorganisent-ils l'examen ?","options":["Regrouper les candidats avec un seul appareil d'enregistrement.","Utiliser deux salles puis changer après le premier groupe.","Annuler les oraux d'une classe jusqu'à vendredi.","Changer l'heure de début et utiliser une seule salle."],"correct":"B","explanation":"Les enseignants utilisent deux salles avec un échange à midi pour bénéficier du matériel.","transcript":"Question 27.\nLes deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle.\nJe peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure.\nLe matériel d'enregistrement est installé dans la salle douze.\nAlors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard.\nParfait, j'envoie le nouveau plan aux étudiants.\nComment les deux enseignants réorganisent-ils l'examen ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Les deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle."},{"voice":"female","text":"Je peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure."},{"voice":"male","text":"Le matériel d'enregistrement est installé dans la salle douze."},{"voice":"female","text":"Alors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard."},{"voice":"male","text":"Parfait, j'envoie le nouveau plan aux étudiants."},{"voice":"female","text":"Comment les deux enseignants réorganisent-ils l'examen ?"}],"audio":"q-27.mp3","audioSeconds":33.719,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quel changement rendrait l'évaluation plus équitable selon l'experte ?","options":["Proposer systématiquement des épreuves moins longues.","Évaluer surtout la rapidité de lecture des consignes.","Réduire les connaissances requises pour tous les candidats.","Adapter les supports tout en conservant le niveau exigé."],"correct":"D","explanation":"L'experte veut rendre le support accessible tout en préservant l'objectif de mesure.","transcript":"Question 28.\nCertaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?\nParce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances.\nQuel changement rendrait l'évaluation plus équitable selon l'experte ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Certaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?"},{"voice":"female","text":"Parce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances."},{"voice":"female","text":"Quel changement rendrait l'évaluation plus équitable selon l'experte ?"}],"audio":"q-28.mp3","audioSeconds":39.917,"slotSeconds":66},{"number":29,"kind":"debate","question":"Sur quoi les deux invités s'opposent-ils principalement ?","options":["Le choix des logiciels de correction en classe.","Le risque d'accuser un élève à partir d'un score automatisé.","La durée nécessaire aux professeurs pour citer les sources.","La difficulté d'obtenir les brouillons de tous les élèves."],"correct":"B","explanation":"Le débat concerne le poids des logiciels de détection dans une décision disciplinaire.","transcript":"Question 29.\nLes enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?\nIls peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices.\nMais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance.\nNous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement.\nD'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche.\nSur quoi les deux invités s'opposent-ils principalement ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Les enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?","speaker":"female"},{"voice":"male","text":"Ils peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices.","speaker":"male"},{"voice":"female","text":"Mais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance.","speaker":"female_alt"},{"voice":"male","text":"Nous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement.","speaker":"male"},{"voice":"female","text":"D'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche.","speaker":"female_alt"},{"voice":"female","text":"Sur quoi les deux invités s'opposent-ils principalement ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":42.24,"slotSeconds":69},{"number":30,"kind":"interview","question":"Pourquoi la responsable a-t-elle modifié les visites du musée ?","options":["Traduire chaque phrase à l'identique dans toutes les langues.","Adapter les visites aux références des différents publics.","Créer des visites séparées avec des collections différentes.","Réduire la diversité des publics pour simplifier les parcours."],"correct":"B","explanation":"Les visites tiennent compte des références culturelles, au-delà d'une traduction littérale.","transcript":"Question 30.\nVotre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?\nNous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers.\nPourquoi la responsable a-t-elle modifié les visites du musée ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?"},{"voice":"female","text":"Nous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers."},{"voice":"female","text":"Pourquoi la responsable a-t-elle modifié les visites du musée ?"}],"audio":"q-30.mp3","audioSeconds":38.611,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quel principe d'apprentissage la conférencière met-elle en avant ?","options":["Espacer les révisions et revenir sur les mots appris.","Réviser intensivement le contenu juste avant l'examen.","Réduire les exercices de mémoire après une première lecture.","Concentrer les séances longues sur la fin de la formation."],"correct":"A","explanation":"L'exposé valorise les rappels espacés et répétés, avec prudence sur la généralisation.","transcript":"Question 31.\nUne étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage.\nQuel principe d'apprentissage la conférencière met-elle en avant ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Une étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage."},{"voice":"female","text":"Quel principe d'apprentissage la conférencière met-elle en avant ?"}],"audio":"q-31.mp3","audioSeconds":39.085,"slotSeconds":69},{"number":32,"kind":"interview","question":"Comment l'université devrait-elle utiliser le modèle de décrochage ?","options":["Utiliser le risque estimé pour limiter les inscriptions suivantes.","Utiliser le risque estimé pour proposer un soutien non stigmatisant.","Utiliser le score comme preuve d'une incapacité à réussir.","Utiliser la prédiction pour remplacer tous les entretiens."],"correct":"B","explanation":"Le modèle doit déclencher un soutien non stigmatisant et être vérifié.","transcript":"Question 32.\nVotre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?\nUn signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction.\nComment l'université devrait-elle utiliser le modèle de décrochage ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Votre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?"},{"voice":"female","text":"Un signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction."},{"voice":"female","text":"Comment l'université devrait-elle utiliser le modèle de décrochage ?"}],"audio":"q-32.mp3","audioSeconds":39.597,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?","options":["Les abandons ne concernent pas les formations du soir.","La progression des élèves se mesure seulement par les présences.","Les taux de réussite augmentent toujours avec les inscriptions.","Le nombre d'inscrits ne permet pas de connaître les acquis réels."],"correct":"D","explanation":"Il souhaite évaluer progression et abandon, pas seulement l'intérêt initial.","transcript":"Question 33.\nLe centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons.\nQuelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"male","text":"Le centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons."},{"voice":"female","text":"Quelle réserve le chroniqueur formule-t-il à propos du succès annoncé ?"}],"audio":"q-33.mp3","audioSeconds":38.017,"slotSeconds":68},{"number":34,"kind":"roundtable","question":"Quel accord se dégage à propos des outils numériques ?","options":["Supprimer le papier une fois l'ordinateur installé dans l'école.","Réserver les devoirs numériques aux élèves qui ont Internet.","Conserver des alternatives aux devoirs numériques.","Imposer les mêmes supports à domicile et dans les classes."],"correct":"C","explanation":"Les interlocuteurs associent activités numériques, documents papier et accès à une salle équipée.","transcript":"Question 34.\nPlusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?\nLes enseignants gagnent du temps pour donner des retours rapides.\nLes parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable.\nNous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes.\nEt ouvrir la salle informatique après les cours pour les élèves qui en ont besoin.\nOui, évaluons les deux possibilités avant de retirer une solution.\nQuel accord se dégage à propos des outils numériques ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Plusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?","speaker":"female"},{"voice":"male","text":"Les enseignants gagnent du temps pour donner des retours rapides.","speaker":"male"},{"voice":"female","text":"Les parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes.","speaker":"male"},{"voice":"female","text":"Et ouvrir la salle informatique après les cours pour les élèves qui en ont besoin.","speaker":"female_alt"},{"voice":"male","text":"Oui, évaluons les deux possibilités avant de retirer une solution.","speaker":"male"},{"voice":"female","text":"Quel accord se dégage à propos des outils numériques ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":38.922,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée le chercheur remet-il en cause ?","options":["L'intérêt pour l'activité contribue aux progrès de l'élève.","L'intervention du professeur soutient le travail de l'élève.","L'ajustement du niveau suffit à faire progresser l'élève.","La clarté des consignes facilite le travail de l'élève."],"correct":"C","explanation":"Le chercheur refuse de considérer le réglage automatique du niveau comme une garantie de progrès. Il soutient au contraire la clarté des consignes, le sens de l'activité et l'accompagnement du professeur.","transcript":"Question 35.\nVotre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?\nParce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel.\nQuelle idée le chercheur remet-il en cause ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"female","text":"Votre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?"},{"voice":"male","text":"Parce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel."},{"voice":"female","text":"Quelle idée le chercheur remet-il en cause ?"}],"audio":"q-35.mp3","audioSeconds":37.838,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition la participation des élèves est-elle utile ?","options":["Confier uniquement aux adultes la rédaction des propositions.","Demander aux élèves de confirmer les choix déjà effectués.","Donner aux élèves une influence réelle sur certaines décisions.","Organiser un vote sans ouvrir la discussion des contraintes."],"correct":"C","explanation":"La participation exige un échange réel, des alternatives et un retour motivé.","transcript":"Question 36.\nVotre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?\nPas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition.\nÀ quelle condition la participation des élèves est-elle utile ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?"},{"voice":"female","text":"Pas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition."},{"voice":"female","text":"À quelle condition la participation des élèves est-elle utile ?"}],"audio":"q-36.mp3","audioSeconds":36.851,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?","options":["Les avis favorables prouvent que la réforme n'a aucun coût.","Les familles ont reçu des versions différentes du calendrier.","L'impact du calendrier varie selon les contraintes familiales.","Les parents ne savent pas quels horaires ont été modifiés."],"correct":"C","explanation":"Elle relie les récits aux différences de situations et aux données vérifiables.","transcript":"Question 37.\nLes élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?\nParce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre.\nPourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?"},{"voice":"female","text":"Parce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des avis divergents sur la réforme ?"}],"audio":"q-37.mp3","audioSeconds":42.059,"slotSeconds":70},{"number":38,"kind":"public-lecture","question":"Quel paradoxe la conférence met-elle en évidence ?","options":["Le nombre d'inscrits diminue lorsque l'aide est bien organisée.","Une forte participation garantit la réussite de chaque élève.","La gratuité empêche les élèves de profiter d'un suivi régulier.","Une forte demande peut réduire la qualité du soutien scolaire."],"correct":"D","explanation":"L'affluence peut dépasser les moyens et réduire la qualité du suivi.","transcript":"Question 38.\nL'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin.\nQuel paradoxe la conférence met-elle en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"L'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin."},{"voice":"female","text":"Quel paradoxe la conférence met-elle en évidence ?"}],"audio":"q-38.mp3","audioSeconds":42.94,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle mesure la responsable juge-t-elle indispensable pour durer ?","options":["Former de nouveaux tuteurs pour stabiliser l'accompagnement.","Augmenter les inscriptions avant de recruter d'autres tuteurs.","Réduire l'accompagnement pour accueillir davantage de familles.","S'appuyer uniquement sur les bénévoles du premier trimestre."],"correct":"A","explanation":"Elle privilégie la formation, la relève et la stabilité du suivi.","transcript":"Question 39.\nVotre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?\nNous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique.\nQuelle mesure la responsable juge-t-elle indispensable pour durer ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?"},{"voice":"female","text":"Nous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique."},{"voice":"female","text":"Quelle mesure la responsable juge-t-elle indispensable pour durer ?"}],"audio":"q-39.mp3","audioSeconds":40.032,"slotSeconds":81}]},{"id":"tcf-listening-05","version":"tcf-listening-2026-11-test05-v3","title":"TCF Listening · Test 05","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La locataire désigne une tache humide au mur pendant une visite du gestionnaire.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Une locataire choisit la peinture avec un décorateur. B. Le gestionnaire installe une étagère dans l'entrée. C. Une locataire montre une infiltration au gestionnaire. D. Le gestionnaire apporte des clés à la nouvelle locataire.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une locataire choisit la peinture avec un décorateur. B. Le gestionnaire installe une étagère dans l'entrée. C. Une locataire montre une infiltration au gestionnaire. D. Le gestionnaire apporte des clés à la nouvelle locataire."}],"audio":"q-01.mp3","audioSeconds":20.973,"slotSeconds":34,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Un travailleur pose des panneaux d'isolation entre les poutres de la toiture.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. L'ouvrier installe de l'isolant sous le toit. B. L'ouvrier transporte un tapis dans l'escalier. C. L'ouvrier mesure une porte avant son remplacement. D. L'ouvrier répare une tuile sur la façade.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'ouvrier installe de l'isolant sous le toit. B. L'ouvrier transporte un tapis dans l'escalier. C. L'ouvrier mesure une porte avant son remplacement. D. L'ouvrier répare une tuile sur la façade."}],"audio":"q-02.mp3","audioSeconds":18.907,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Le résident lit un panneau affichant les dates de maintenance.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. Le résident dépose un courrier dans la boîte commune. B. Le résident consulte l'avis de travaux dans le hall. C. Le résident attend l'ouverture du local à vélos. D. Le résident vérifie une facture près de l'ascenseur.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le résident dépose un courrier dans la boîte commune. B. Le résident consulte l'avis de travaux dans le hall. C. Le résident attend l'ouverture du local à vélos. D. Le résident vérifie une facture près de l'ascenseur."}],"audio":"q-03.mp3","audioSeconds":20.556,"slotSeconds":34,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Deux habitants jardinent dans des bacs de la cour partagée.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Des habitants nettoient une allée après les travaux. B. Des habitants déplacent des meubles dans une cour. C. Des habitants posent une clôture autour d'un parking. D. Des habitants plantent des fleurs dans leur cour.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Des habitants nettoient une allée après les travaux. B. Des habitants déplacent des meubles dans une cour. C. Des habitants posent une clôture autour d'un parking. D. Des habitants plantent des fleurs dans leur cour."}],"audio":"q-04.mp3","audioSeconds":20.567,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La personne doit signaler la fuite au service chargé des réparations.","transcript":"Question 5.\nLe robinet de la cuisine fuit. À qui dois-je le signaler ?\nA. Au service d'entretien de l'immeuble. B. Au propriétaire du commerce voisin. C. Au responsable de la collecte des déchets. D. Au comptable de l'agence immobilière.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Le robinet de la cuisine fuit. À qui dois-je le signaler ?"},{"voice":"male","text":"A. Au service d'entretien de l'immeuble. B. Au propriétaire du commerce voisin. C. Au responsable de la collecte des déchets. D. Au comptable de l'agence immobilière."}],"audio":"q-05.mp3","audioSeconds":19.812,"slotSeconds":33},{"number":6,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse correcte accepte la visite vendredi et propose dix-sept heures. Les autres propositions concernent les chambres, le paiement et la localisation.","transcript":"Question 6.\nPouvez-vous déplacer la visite de l'appartement à vendredi ?\nA. La caution est payable à la signature. B. Le logement dispose de deux chambres. C. Oui, vendredi à dix-sept heures conviendrait. D. Oui, il se trouve près de la station.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Pouvez-vous déplacer la visite de l'appartement à vendredi ?"},{"voice":"female","text":"A. La caution est payable à la signature. B. Le logement dispose de deux chambres. C. Oui, vendredi à dix-sept heures conviendrait. D. Oui, il se trouve près de la station."}],"audio":"q-06.mp3","audioSeconds":19.22,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse propose explicitement de fournir une copie du document.","transcript":"Question 7.\nAvez-vous une copie du règlement de l'immeuble ?\nA. Je vais prévenir tous les résidents. B. Il s'applique à tous les étages. C. Il a été voté le mois dernier. D. Je peux vous en imprimer un exemplaire.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Avez-vous une copie du règlement de l'immeuble ?"},{"voice":"male","text":"A. Je vais prévenir tous les résidents. B. Il s'applique à tous les étages. C. Il a été voté le mois dernier. D. Je peux vous en imprimer un exemplaire."}],"audio":"q-07.mp3","audioSeconds":17.287,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse correcte annonce l'intervention du technicien demain matin, ce qui fournit l'échéance de réparation demandée.","transcript":"Question 8.\nL'ascenseur est encore en panne. Savez-vous quand il sera réparé ?\nA. Il se trouve au fond du couloir. B. Le technicien doit intervenir demain matin. C. Il dessert actuellement six étages. D. Il a été installé il y a deux ans.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"L'ascenseur est encore en panne. Savez-vous quand il sera réparé ?"},{"voice":"female","text":"A. Il se trouve au fond du couloir. B. Le technicien doit intervenir demain matin. C. Il dessert actuellement six étages. D. Il a été installé il y a deux ans."}],"audio":"q-08.mp3","audioSeconds":20.039,"slotSeconds":38},{"number":9,"kind":"announcement","question":"À quel moment l'ascenseur sera-t-il indisponible ?","options":["Jeudi matin, entre neuf heures et midi.","Mercredi matin, entre neuf heures et midi.","Vendredi matin, entre neuf heures et midi.","Jeudi après-midi, entre treize et seize heures."],"correct":"A","explanation":"L'arrêt est annoncé jeudi entre neuf heures et midi.","transcript":"Question 9.\nLa copropriété du boulevard Victor-Hugo informe les résidents qu'une inspection de l'ascenseur aura lieu jeudi entre neuf heures et midi. L'appareil restera à l'arrêt pendant ce créneau, mais il sera remis en service dans l'après-midi. Les escaliers demeureront accessibles. Les livraisons volumineuses doivent être reportées.\nÀ quel moment l'ascenseur sera-t-il indisponible ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"La copropriété du boulevard Victor-Hugo informe les résidents qu'une inspection de l'ascenseur aura lieu jeudi entre neuf heures et midi. L'appareil restera à l'arrêt pendant ce créneau, mais il sera remis en service dans l'après-midi. Les escaliers demeureront accessibles. Les livraisons volumineuses doivent être reportées."},{"voice":"female","text":"À quel moment l'ascenseur sera-t-il indisponible ?"}],"audio":"q-09.mp3","audioSeconds":23.042,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi la candidate souhaite-t-elle revenir visiter l'appartement ?","options":["Elle veut vérifier le bruit du restaurant le soir.","Elle veut comparer le loyer avec celui des voisins.","Elle veut vérifier le temps du trajet vers son travail.","Elle veut revoir la cuisine avant sa rénovation."],"correct":"A","explanation":"La visite du soir permet d'évaluer le bruit lié au restaurant.","transcript":"Question 10.\nCet appartement vous convient-il ? La cuisine a été rénovée et la chambre donne sur la cour.\nLa pièce est agréable, mais le restaurant au rez-de-chaussée ferme très tard. J'aimerais revenir un soir pour entendre le bruit.\nNous pouvons organiser une deuxième visite à vingt heures.\nMerci. Le loyer me convient, mais je voudrais être sûre de pouvoir dormir.\nPourquoi la candidate souhaite-t-elle revenir visiter l'appartement ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Cet appartement vous convient-il ? La cuisine a été rénovée et la chambre donne sur la cour."},{"voice":"female","text":"La pièce est agréable, mais le restaurant au rez-de-chaussée ferme très tard. J'aimerais revenir un soir pour entendre le bruit."},{"voice":"male","text":"Nous pouvons organiser une deuxième visite à vingt heures."},{"voice":"female","text":"Merci. Le loyer me convient, mais je voudrais être sûre de pouvoir dormir."},{"voice":"female","text":"Pourquoi la candidate souhaite-t-elle revenir visiter l'appartement ?"}],"audio":"q-10.mp3","audioSeconds":29.532,"slotSeconds":44},{"number":11,"kind":"announcement","question":"Quand faut-il transmettre les demandes de réparation ?","options":["Dès mercredi matin pour les réparations urgentes.","Avant mardi soir pour les réparations ordinaires.","Avant mardi midi pour les réparations ordinaires.","La semaine prochaine pour les réparations urgentes."],"correct":"C","explanation":"Les demandes ordinaires sont attendues avant mardi midi, les urgences étant immédiates.","transcript":"Question 11.\nLa société de gestion rappelle aux résidents de l'immeuble des Tilleuls que les réparations non urgentes seront regroupées la semaine prochaine. Afin de planifier l'intervention, merci de transmettre la description du problème avant mardi midi. Les fuites importantes et les pannes dangereuses doivent toujours être signalées immédiatement par téléphone.\nQuand faut-il transmettre les demandes de réparation ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"La société de gestion rappelle aux résidents de l'immeuble des Tilleuls que les réparations non urgentes seront regroupées la semaine prochaine. Afin de planifier l'intervention, merci de transmettre la description du problème avant mardi midi. Les fuites importantes et les pannes dangereuses doivent toujours être signalées immédiatement par téléphone."},{"voice":"female","text":"Quand faut-il transmettre les demandes de réparation ?"}],"audio":"q-11.mp3","audioSeconds":26.285,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle solution l'artisan propose-t-il pour les travaux ?","options":["Remplacer la douche sans modifier la ventilation.","Traiter les infiltrations avant de refaire le décor.","Refaire le carrelage avant de réparer les joints.","Réduire le devis en reportant la réfection des joints."],"correct":"B","explanation":"Ils choisissent d'abord l'étanchéité et la ventilation, en reportant les finitions.","transcript":"Question 12.\nLe devis prévoit de refaire toute la salle de bains, mais notre budget ne le permet pas.\nNous pouvons réparer d'abord l'étanchéité autour de la douche. Le changement du carrelage peut attendre.\nEst-ce que cela règle le problème d'humidité ?\nOui, si l'on traite aussi le joint et si l'on vérifie la ventilation. Je vous prépare un devis réduit.\nD'accord, faisons les travaux indispensables en priorité.\nQuelle solution l'artisan propose-t-il pour les travaux ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Le devis prévoit de refaire toute la salle de bains, mais notre budget ne le permet pas."},{"voice":"male","text":"Nous pouvons réparer d'abord l'étanchéité autour de la douche. Le changement du carrelage peut attendre."},{"voice":"female","text":"Est-ce que cela règle le problème d'humidité ?"},{"voice":"male","text":"Oui, si l'on traite aussi le joint et si l'on vérifie la ventilation. Je vous prépare un devis réduit."},{"voice":"female","text":"D'accord, faisons les travaux indispensables en priorité."},{"voice":"female","text":"Quelle solution l'artisan propose-t-il pour les travaux ?"}],"audio":"q-12.mp3","audioSeconds":29.986,"slotSeconds":43},{"number":13,"kind":"announcement","question":"À quelle période les travaux bruyants sont-ils autorisés ?","options":["En semaine, de sept heures trente à dix-huit heures trente.","En semaine, de huit heures trente à dix-sept heures trente.","Le dimanche, de huit heures trente à dix-sept heures trente.","Le dimanche, de neuf heures trente à seize heures trente."],"correct":"B","explanation":"Les travaux bruyants sont limités au créneau indiqué en semaine et exclus le dimanche.","transcript":"Question 13.\nDans le cadre des travaux de façade, la mairie rappelle que les outils très bruyants ne peuvent être utilisés avant huit heures trente ni après dix-sept heures trente en semaine. Ils sont interdits le dimanche. Les opérations silencieuses, comme la peinture intérieure, restent possibles en dehors de ces horaires selon le règlement de l'immeuble.\nÀ quelle période les travaux bruyants sont-ils autorisés ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Dans le cadre des travaux de façade, la mairie rappelle que les outils très bruyants ne peuvent être utilisés avant huit heures trente ni après dix-sept heures trente en semaine. Ils sont interdits le dimanche. Les opérations silencieuses, comme la peinture intérieure, restent possibles en dehors de ces horaires selon le règlement de l'immeuble."},{"voice":"female","text":"À quelle période les travaux bruyants sont-ils autorisés ?"}],"audio":"q-13.mp3","audioSeconds":24.296,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quel arrangement les voisins choisissent-ils pour la cour ?","options":["Conserver l'horaire et déplacer le repas dans le hall commun.","Commencer le repas plus tôt et le terminer avant vingt heures.","Garder l'horaire du repas et éloigner les tables des fenêtres.","Reporter le repas au dimanche pour éviter le coucher des enfants."],"correct":"B","explanation":"Les voisins envisagent un repas plus tôt et terminé avant vingt heures.","transcript":"Question 14.\nNous voulions organiser un repas collectif samedi soir, mais des enfants se couchent tôt dans les appartements qui donnent sur la cour.\nEt si nous commencions en fin d'après-midi, puis terminions avant vingt heures ?\nCela me paraît raisonnable. Nous pourrions aussi installer les tables loin des fenêtres.\nJe vais en parler au conseil des résidents et vérifier si tout le monde est d'accord.\nQuel arrangement les voisins choisissent-ils pour la cour ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Nous voulions organiser un repas collectif samedi soir, mais des enfants se couchent tôt dans les appartements qui donnent sur la cour."},{"voice":"female","text":"Et si nous commencions en fin d'après-midi, puis terminions avant vingt heures ?"},{"voice":"male","text":"Cela me paraît raisonnable. Nous pourrions aussi installer les tables loin des fenêtres."},{"voice":"female","text":"Je vais en parler au conseil des résidents et vérifier si tout le monde est d'accord."},{"voice":"female","text":"Quel arrangement les voisins choisissent-ils pour la cour ?"}],"audio":"q-14.mp3","audioSeconds":29.561,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Pourquoi certains ménages ne demandent-ils pas encore l'aide annoncée ?","options":["Ils craignent de payer davantage de charges après l'isolation.","Ils craignent de perdre leur bail pendant les travaux prévus.","Ils pensent devoir avancer la totalité du coût de l'isolation.","Ils pensent que les aides concernent les propriétaires occupants."],"correct":"A","explanation":"Le reportage mentionne la peur que les charges augmentent après isolation.","transcript":"Question 15.\nLa métropole de Dijon a lancé une aide à l'isolation des logements anciens. Les premières demandes sont nombreuses, mais plusieurs associations signalent que des locataires hésitent à entamer la procédure. Ils craignent que leurs propriétaires répercutent ensuite une partie des travaux sur les charges. La collectivité prévoit une permanence juridique afin d'expliquer les protections et les obligations de chacun.\nPourquoi certains ménages ne demandent-ils pas encore l'aide annoncée ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"La métropole de Dijon a lancé une aide à l'isolation des logements anciens. Les premières demandes sont nombreuses, mais plusieurs associations signalent que des locataires hésitent à entamer la procédure. Ils craignent que leurs propriétaires répercutent ensuite une partie des travaux sur les charges. La collectivité prévoit une permanence juridique afin d'expliquer les protections et les obligations de chacun."},{"voice":"female","text":"Pourquoi certains ménages ne demandent-ils pas encore l'aide annoncée ?"}],"audio":"q-15.mp3","audioSeconds":28.253,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi le plombier ne pourra-t-il pas venir lundi ?","options":["Il doit attendre une pièce pour la tuyauterie de la buanderie.","Il doit finir une intervention urgente dans un immeuble voisin.","Il doit faire valider son devis par le gestionnaire de l'immeuble.","Il doit attendre que les habitants aient vidé la buanderie commune."],"correct":"B","explanation":"Un chantier urgent ailleurs empêche sa venue lundi.","transcript":"Question 16.\nJe vous avais réservé le lundi matin pour réparer la tuyauterie de la buanderie.\nJe dois terminer une intervention urgente dans un immeuble voisin et je ne pourrai pas être là avant mardi.\nLa fuite est maîtrisée pour l'instant. Mardi à neuf heures, cela vous irait ?\nOui. Je vous confirmerai par message et vous présenterai le matériel nécessaire.\nPourquoi le plombier ne pourra-t-il pas venir lundi ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Je vous avais réservé le lundi matin pour réparer la tuyauterie de la buanderie."},{"voice":"male","text":"Je dois terminer une intervention urgente dans un immeuble voisin et je ne pourrai pas être là avant mardi."},{"voice":"female","text":"La fuite est maîtrisée pour l'instant. Mardi à neuf heures, cela vous irait ?"},{"voice":"male","text":"Oui. Je vous confirmerai par message et vous présenterai le matériel nécessaire."},{"voice":"female","text":"Pourquoi le plombier ne pourra-t-il pas venir lundi ?"}],"audio":"q-16.mp3","audioSeconds":25.121,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Quel service sera interrompu mercredi matin ?","options":["L'eau froide du bâtiment A seulement, entre huit et onze heures.","Le chauffage des bâtiments A et B, entre huit et onze heures.","L'eau froide des bâtiments A et B, entre huit et onze heures.","Le chauffage du bâtiment B seulement, entre huit et onze heures."],"correct":"C","explanation":"L'annonce précise une coupure d'eau froide limitée à deux bâtiments.","transcript":"Question 17.\nEn raison du remplacement d'une vanne principale, l'eau froide sera coupée dans les bâtiments A et B mercredi de huit heures à onze heures. Le chauffage collectif continuera à fonctionner normalement. Les habitants sont invités à remplir quelques récipients à l'avance. En cas de problème après la remise en service, contactez le gardien.\nQuel service sera interrompu mercredi matin ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"En raison du remplacement d'une vanne principale, l'eau froide sera coupée dans les bâtiments A et B mercredi de huit heures à onze heures. Le chauffage collectif continuera à fonctionner normalement. Les habitants sont invités à remplir quelques récipients à l'avance. En cas de problème après la remise en service, contactez le gardien."},{"voice":"female","text":"Quel service sera interrompu mercredi matin ?"}],"audio":"q-17.mp3","audioSeconds":26.755,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la locataire demande-t-elle une vérification de son paiement ?","options":["Son virement récent porte la référence d'un autre appartement.","Son changement de banque a entraîné le rejet de son paiement.","Son échéance de paiement a changé depuis son dernier virement.","Son loyer payé apparaît encore comme restant dû sur son compte."],"correct":"D","explanation":"Un changement de compte semble avoir empêché le rapprochement du paiement.","transcript":"Question 18.\nBonjour, j'ai réglé mon loyer le premier du mois, pourtant votre espace en ligne m'indique un retard.\nAvez-vous changé de banque récemment ?\nOui, le virement part désormais d'un nouveau compte, mais la référence du logement est restée la même.\nJe vais comparer les opérations reçues et vous envoyer une confirmation avant de modifier votre dossier.\nMerci, je préfère éviter un rappel injustifié.\nPourquoi la locataire demande-t-elle une vérification de son paiement ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Bonjour, j'ai réglé mon loyer le premier du mois, pourtant votre espace en ligne m'indique un retard."},{"voice":"male","text":"Avez-vous changé de banque récemment ?"},{"voice":"female","text":"Oui, le virement part désormais d'un nouveau compte, mais la référence du logement est restée la même."},{"voice":"male","text":"Je vais comparer les opérations reçues et vous envoyer une confirmation avant de modifier votre dossier."},{"voice":"female","text":"Merci, je préfère éviter un rappel injustifié."},{"voice":"female","text":"Pourquoi la locataire demande-t-elle une vérification de son paiement ?"}],"audio":"q-18.mp3","audioSeconds":30.462,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la réunion des locataires est-elle organisée ?","options":["Pour choisir le conseil qui fixera le budget des prochaines rénovations.","Pour préparer la décision en recueillant les questions des résidents.","Pour répartir les frais des travaux entre les différents appartements.","Pour approuver le calendrier des travaux par un vote des résidents."],"correct":"B","explanation":"La réunion est préparatoire, destinée à informer et recueillir des besoins avant un vote ultérieur.","transcript":"Question 19.\nL'association des habitants tiendra mercredi une réunion sur les prochaines rénovations de l'immeuble. Les résidents pourront consulter le calendrier prévisionnel, poser des questions sur les accès temporaires et signaler les besoins particuliers liés au déménagement de certains meubles. Aucun vote ne sera organisé ce soir-là; une décision formelle interviendra lors de l'assemblée du mois prochain.\nPourquoi la réunion des locataires est-elle organisée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"L'association des habitants tiendra mercredi une réunion sur les prochaines rénovations de l'immeuble. Les résidents pourront consulter le calendrier prévisionnel, poser des questions sur les accès temporaires et signaler les besoins particuliers liés au déménagement de certains meubles. Aucun vote ne sera organisé ce soir-là; une décision formelle interviendra lors de l'assemblée du mois prochain."},{"voice":"female","text":"Pourquoi la réunion des locataires est-elle organisée ?"}],"audio":"q-19.mp3","audioSeconds":27.243,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle difficulté inquiète le résident ?","options":["La distance de son logement à l'hébergement prévu durant les travaux.","La durée du relogement provisoire pour sa mère pendant les travaux.","La largeur de l'accès provisoire pour sa mère qui marche avec une aide.","Le prix des aménagements que sa mère devra payer après les travaux."],"correct":"C","explanation":"Il s'inquiète de l'accessibilité pour sa mère avec un déambulateur.","transcript":"Question 20.\nLe nouveau plan d'accès me plaît, mais ma mère utilise un déambulateur et habite au deuxième étage.\nLes travaux d'entrée doivent durer deux semaines, avec une rampe provisoire.\nJ'aimerais vérifier que la rampe sera suffisamment large, surtout les jours où l'ascenseur est immobilisé.\nJe vais demander à l'entreprise un plan coté et organiser un essai avec les résidents concernés.\nQuelle difficulté inquiète le résident ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Le nouveau plan d'accès me plaît, mais ma mère utilise un déambulateur et habite au deuxième étage."},{"voice":"female","text":"Les travaux d'entrée doivent durer deux semaines, avec une rampe provisoire."},{"voice":"male","text":"J'aimerais vérifier que la rampe sera suffisamment large, surtout les jours où l'ascenseur est immobilisé."},{"voice":"female","text":"Je vais demander à l'entreprise un plan coté et organiser un essai avec les résidents concernés."},{"voice":"female","text":"Quelle difficulté inquiète le résident ?"}],"audio":"q-20.mp3","audioSeconds":28.133,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pourquoi les habitants doivent-ils préciser leurs disponibilités ?","options":["Pour répartir les entretiens entre plusieurs créneaux accessibles.","Pour organiser les travaux selon les horaires des résidents absents.","Pour fixer une réunion commune à tous les résidents de l'immeuble.","Pour confier les entretiens aux habitants disponibles le samedi."],"correct":"A","explanation":"Les disponibilités servent à organiser des entretiens accessibles à différents horaires.","transcript":"Question 21.\nLe conseil de quartier prépare une consultation des résidents sur l'usage de la cour commune. Les entretiens individuels auront lieu le soir et le samedi. Comme plusieurs personnes travaillent en horaires décalés, nous vous invitons à indiquer au moins deux créneaux possibles. Ces informations permettront de répartir les rendez-vous sans concentrer tous les échanges sur le même après-midi.\nPourquoi les habitants doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Le conseil de quartier prépare une consultation des résidents sur l'usage de la cour commune. Les entretiens individuels auront lieu le soir et le samedi. Comme plusieurs personnes travaillent en horaires décalés, nous vous invitons à indiquer au moins deux créneaux possibles. Ces informations permettront de répartir les rendez-vous sans concentrer tous les échanges sur le même après-midi."},{"voice":"female","text":"Pourquoi les habitants doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":26.616,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel bénéfice l'habitante met-elle surtout en avant ?","options":["Les tâches réparties qui diminuent le besoin d'entretien de la cour.","Les décisions communes qui évitent les désaccords sur l'arrosage.","Les échanges réguliers qui rapprochent les voisins de l'immeuble.","Les récoltes partagées qui réduisent les dépenses des habitants."],"correct":"C","explanation":"La participante valorise les relations humaines plutôt que le rendement du jardin.","transcript":"Question 22.\nDepuis la création du jardin collectif dans la cour, votre immeuble semble plus animé. Qu'est-ce qui a changé pour vous ?\nJe cultive quelques herbes, mais ce n'est pas l'essentiel. Avant, les voisins se croisaient sans se parler. Maintenant nous échangeons des conseils, décidons ensemble de l'arrosage et apprenons à résoudre de petits désaccords. Il arrive que des plantes meurent, mais les contacts continuent. Pour moi, ce sont surtout ces relations qui rendent l'expérience précieuse.\nQuel bénéfice l'habitante met-elle surtout en avant ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Depuis la création du jardin collectif dans la cour, votre immeuble semble plus animé. Qu'est-ce qui a changé pour vous ?"},{"voice":"female","text":"Je cultive quelques herbes, mais ce n'est pas l'essentiel. Avant, les voisins se croisaient sans se parler. Maintenant nous échangeons des conseils, décidons ensemble de l'arrosage et apprenons à résoudre de petits désaccords. Il arrive que des plantes meurent, mais les contacts continuent. Pour moi, ce sont surtout ces relations qui rendent l'expérience précieuse."},{"voice":"female","text":"Quel bénéfice l'habitante met-elle surtout en avant ?"}],"audio":"q-22.mp3","audioSeconds":34.79,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Quel compromis les intervenants finissent-ils par envisager ?","options":["Tester la rénovation d'un bâtiment avec suivi des coûts et protection sociale.","Faire voter les locataires avant de définir les garanties sur les charges futures.","Lancer les travaux du premier bâtiment en reportant le suivi des consommations.","Rénover plusieurs bâtiments puis négocier les aides selon les dépenses finales."],"correct":"A","explanation":"Le compromis est un essai dans un bâtiment avec suivi des charges et protection des ménages.","transcript":"Question 23.\nNous discutons du partage du coût de la rénovation énergétique.\nLes propriétaires souhaitent isoler les façades rapidement pour réduire les pertes de chaleur.\nLes représentants des locataires veulent des garanties sur les charges et sur la durée du chantier.\nNous pourrions commencer par un seul bâtiment, mesurer les consommations pendant l'hiver et publier les dépenses exactes.\nOui, à condition de prévoir une aide pour les ménages les plus fragiles si une augmentation temporaire est nécessaire.\nDans ce cas, élaborons ensemble un accord avant d'étendre les travaux.\nQuel compromis les intervenants finissent-ils par envisager ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Nous discutons du partage du coût de la rénovation énergétique.","speaker":"female"},{"voice":"male","text":"Les propriétaires souhaitent isoler les façades rapidement pour réduire les pertes de chaleur.","speaker":"male"},{"voice":"female","text":"Les représentants des locataires veulent des garanties sur les charges et sur la durée du chantier.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions commencer par un seul bâtiment, mesurer les consommations pendant l'hiver et publier les dépenses exactes.","speaker":"male"},{"voice":"female","text":"Oui, à condition de prévoir une aide pour les ménages les plus fragiles si une augmentation temporaire est nécessaire.","speaker":"female_alt"},{"voice":"male","text":"Dans ce cas, élaborons ensemble un accord avant d'étendre les travaux.","speaker":"male"},{"voice":"female","text":"Quel compromis les intervenants finissent-ils par envisager ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":40.62,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle faiblesse l'urbaniste relève-t-elle dans l'enquête ?","options":["Les personnes interrogées habitaient surtout les étages rénovés en premier.","Les répondants avaient surtout participé à la conception des travaux.","Les personnes interrogées occupaient surtout des logements faciles d'accès.","Les personnes interrogées avaient surtout choisi de venir à l'inauguration."],"correct":"D","explanation":"L'enquête n'a interrogé que les personnes volontaires présentes à l'événement.","transcript":"Question 24.\nVotre sondage suggère que les résidents apprécient les espaces rénovés. Pouvez-vous généraliser cette conclusion ?\nPas encore. Nous avons distribué les questionnaires lors de l'inauguration, à des personnes qui avaient choisi de venir. Celles qui ont du mal à sortir de chez elles ou qui se sentent exclues du projet étaient peu présentes. Nous devons rencontrer les habitants d'autres étages, y compris ceux qui rencontrent des difficultés d'accès, pour comprendre l'ensemble des usages. Une inauguration réussie ne garantit pas une amélioration équitable.\nQuelle faiblesse l'urbaniste relève-t-elle dans l'enquête ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre sondage suggère que les résidents apprécient les espaces rénovés. Pouvez-vous généraliser cette conclusion ?"},{"voice":"female","text":"Pas encore. Nous avons distribué les questionnaires lors de l'inauguration, à des personnes qui avaient choisi de venir. Celles qui ont du mal à sortir de chez elles ou qui se sentent exclues du projet étaient peu présentes. Nous devons rencontrer les habitants d'autres étages, y compris ceux qui rencontrent des difficultés d'accès, pour comprendre l'ensemble des usages. Une inauguration réussie ne garantit pas une amélioration équitable."},{"voice":"female","text":"Quelle faiblesse l'urbaniste relève-t-elle dans l'enquête ?"}],"audio":"q-24.mp3","audioSeconds":37.124,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension principale le reportage présente-t-il ?","options":["Une rénovation contestée menace le maintien des familles dans le quartier.","Une rénovation tardive oblige les familles à financer leur isolation.","Une rénovation attendue impose aux familles un relogement difficile.","Une rénovation coûteuse oblige le bailleur à diminuer les aides familiales."],"correct":"C","explanation":"La rénovation est souhaitée, mais elle impose un relogement temporaire complexe.","transcript":"Question 25.\nÀ Brest, un ancien ensemble de logements est en cours de rénovation. Les façades vont être isolées et les fenêtres remplacées.\nNous attendions ces améliorations, témoigne une habitante, mais nous devons quitter nos appartements pendant six semaines. Les solutions de relogement ne conviennent pas toutes aux familles avec enfants.\nLe bailleur promet un accompagnement, tandis que l'association des locataires demande des dates plus précises et la prise en charge des déplacements. Le chantier doit donc avancer sans laisser les habitants supporter seuls ses conséquences.\nQuelle tension principale le reportage présente-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"À Brest, un ancien ensemble de logements est en cours de rénovation. Les façades vont être isolées et les fenêtres remplacées."},{"voice":"male","text":"Nous attendions ces améliorations, témoigne une habitante, mais nous devons quitter nos appartements pendant six semaines. Les solutions de relogement ne conviennent pas toutes aux familles avec enfants."},{"voice":"female","text":"Le bailleur promet un accompagnement, tandis que l'association des locataires demande des dates plus précises et la prise en charge des déplacements. Le chantier doit donc avancer sans laisser les habitants supporter seuls ses conséquences."},{"voice":"female","text":"Quelle tension principale le reportage présente-t-il ?"}],"audio":"q-25.mp3","audioSeconds":37.078,"slotSeconds":71},{"number":26,"kind":"interview","question":"Pourquoi l'architecte refuse-t-il de standardiser toutes les entrées ?","options":["Il faut équiper les entrées avant de consulter les résidents concernés.","Il faut adapter chaque entrée aux contraintes et aux déplacements réels.","Appliquer aux entrées les dimensions du bâtiment le plus récent.","Choisir une rampe commune pour faciliter l'entretien des entrées."],"correct":"B","explanation":"Les situations d'accès diffèrent; il faut mesurer et tester avec les utilisateurs.","transcript":"Question 26.\nVous travaillez sur l'accessibilité des immeubles anciens. Pourquoi ne pas poser partout le même modèle de rampe ?\nParce que les bâtiments n'ont pas les mêmes pentes, les mêmes portes ni les mêmes usages. Une rampe trop étroite peut être techniquement conforme à un plan et pourtant inutilisable avec certains fauteuils. Nous préférons observer les déplacements réels, mesurer les contraintes et tester plusieurs solutions avec les résidents concernés. L'objectif est de rendre l'accès réellement possible, pas simplement d'afficher un équipement neuf.\nPourquoi l'architecte refuse-t-il de standardiser toutes les entrées ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Vous travaillez sur l'accessibilité des immeubles anciens. Pourquoi ne pas poser partout le même modèle de rampe ?"},{"voice":"male","text":"Parce que les bâtiments n'ont pas les mêmes pentes, les mêmes portes ni les mêmes usages. Une rampe trop étroite peut être techniquement conforme à un plan et pourtant inutilisable avec certains fauteuils. Nous préférons observer les déplacements réels, mesurer les contraintes et tester plusieurs solutions avec les résidents concernés. L'objectif est de rendre l'accès réellement possible, pas simplement d'afficher un équipement neuf."},{"voice":"female","text":"Pourquoi l'architecte refuse-t-il de standardiser toutes les entrées ?"}],"audio":"q-26.mp3","audioSeconds":38.854,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quelle solution est adoptée pour le local commun ?","options":["Placer les objets peu utilisés dans le passage commun près de l'entrée.","Réserver le local aux vélos et installer les poussettes au sous-sol.","Réduire la place des vélos pour laisser les poussettes près de la porte.","Créer deux zones de rangement en gardant des passages assez larges."],"correct":"D","explanation":"Ils envisagent des zones distinctes et un passage accessible.","transcript":"Question 27.\nLe local à vélos est devenu trop encombré. Plusieurs poussettes y sont aussi rangées.\nLes familles n'ont pas d'autre espace près de l'entrée.\nNous pourrions tracer deux zones et déplacer les objets rarement utilisés vers le rangement du sous-sol.\nD'accord, mais assurons-nous que les passages restent assez larges pour les poussettes.\nJe préparerai un plan et le soumettrai au conseil.\nQuelle solution est adoptée pour le local commun ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Le local à vélos est devenu trop encombré. Plusieurs poussettes y sont aussi rangées."},{"voice":"female","text":"Les familles n'ont pas d'autre espace près de l'entrée."},{"voice":"male","text":"Nous pourrions tracer deux zones et déplacer les objets rarement utilisés vers le rangement du sous-sol."},{"voice":"female","text":"D'accord, mais assurons-nous que les passages restent assez larges pour les poussettes."},{"voice":"male","text":"Je préparerai un plan et le soumettrai au conseil."},{"voice":"female","text":"Quelle solution est adoptée pour le local commun ?"}],"audio":"q-27.mp3","audioSeconds":31.375,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle critique l'experte adresse-t-elle à la procédure de consultation ?","options":["Les résidents devaient valider les horaires avant de choisir les accès provisoires.","Les résidents devaient choisir les accès sans connaître les plans détaillés.","Les résidents pouvaient modifier des détails, mais pas les choix essentiels.","Les résidents pouvaient modifier le chantier sans connaître ses contraintes."],"correct":"C","explanation":"Les enjeux importants étaient fixés avant que les habitants ne puissent intervenir.","transcript":"Question 28.\nLes plans de rénovation ont été présentés aux résidents avant les travaux. N'est-ce pas suffisant ?\nLa consultation a eu lieu une fois les décisions principales prises. Les habitants pouvaient choisir une couleur de peinture, mais pas discuter de l'emplacement des accès provisoires ou des horaires de chantier. C'est précisément là qu'ils avaient des informations utiles. Nous recommandons d'organiser les échanges plus tôt et de préciser quelles décisions restent ouvertes. Sinon, la participation ressemble davantage à une opération de communication qu'à une influence réelle.\nQuelle critique l'experte adresse-t-elle à la procédure de consultation ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Les plans de rénovation ont été présentés aux résidents avant les travaux. N'est-ce pas suffisant ?"},{"voice":"female","text":"La consultation a eu lieu une fois les décisions principales prises. Les habitants pouvaient choisir une couleur de peinture, mais pas discuter de l'emplacement des accès provisoires ou des horaires de chantier. C'est précisément là qu'ils avaient des informations utiles. Nous recommandons d'organiser les échanges plus tôt et de préciser quelles décisions restent ouvertes. Sinon, la participation ressemble davantage à une opération de communication qu'à une influence réelle."},{"voice":"female","text":"Quelle critique l'experte adresse-t-elle à la procédure de consultation ?"}],"audio":"q-28.mp3","audioSeconds":39.005,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quel désaccord principal oppose les invités ?","options":["L'effet des loyers actuels sur le coût des rénovations des anciens bâtiments.","L'effet de la construction sur les charges des locataires installés.","L'effet des aides aux rénovations sur l'offre de logements abordables.","L'effet du plafonnement sur la protection des locataires et l'offre disponible."],"correct":"D","explanation":"Les invités débattent des effets d'un encadrement sur les loyers et la disponibilité des logements.","transcript":"Question 29.\nFaut-il encadrer davantage les loyers dans les quartiers où les prix augmentent ?\nUne limitation peut protéger les locataires actuels contre des hausses soudaines.\nMais si les propriétaires renoncent à mettre des logements sur le marché, nous risquons de réduire l'offre disponible.\nC'est pourquoi je propose de combiner l'encadrement avec des aides à la rénovation et une production de logements abordables.\nNous sommes d'accord sur le besoin de construire. Nous divergeons surtout sur les conséquences immédiates du plafond de loyer.\nQuel désaccord principal oppose les invités ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Faut-il encadrer davantage les loyers dans les quartiers où les prix augmentent ?","speaker":"female"},{"voice":"male","text":"Une limitation peut protéger les locataires actuels contre des hausses soudaines.","speaker":"male"},{"voice":"female","text":"Mais si les propriétaires renoncent à mettre des logements sur le marché, nous risquons de réduire l'offre disponible.","speaker":"female_alt"},{"voice":"male","text":"C'est pourquoi je propose de combiner l'encadrement avec des aides à la rénovation et une production de logements abordables.","speaker":"male"},{"voice":"female","text":"Nous sommes d'accord sur le besoin de construire. Nous divergeons surtout sur les conséquences immédiates du plafond de loyer.","speaker":"female_alt"},{"voice":"female","text":"Quel désaccord principal oppose les invités ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":36.206,"slotSeconds":64},{"number":30,"kind":"interview","question":"Quelle conception de la rénovation patrimoniale défend l'architecte ?","options":["Rénover l'usine en remplaçant ses traces matérielles par des archives exposées.","Conserver l'usine en limitant les logements aux espaces sans traces anciennes.","Réutiliser l'usine en conservant les traces qui rendent son histoire lisible.","Préserver l'usine en réservant ses anciens espaces de travail aux visites."],"correct":"C","explanation":"Elle associe conservation des traces et réutilisation actuelle du bâtiment.","transcript":"Question 30.\nL'ancienne usine de briques va devenir des logements. Peut-on parler de conservation du patrimoine ?\nOui, si nous rendons lisible son histoire. La grande charpente et certaines traces de machines méritent d'être conservées. Mais nous devons aussi installer des logements confortables, accessibles et peu énergivores. Garder le bâtiment vide ne garantit pas sa survie. Le plus important est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son ancien usage.\nQuelle conception de la rénovation patrimoniale défend l'architecte ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"L'ancienne usine de briques va devenir des logements. Peut-on parler de conservation du patrimoine ?"},{"voice":"female","text":"Oui, si nous rendons lisible son histoire. La grande charpente et certaines traces de machines méritent d'être conservées. Mais nous devons aussi installer des logements confortables, accessibles et peu énergivores. Garder le bâtiment vide ne garantit pas sa survie. Le plus important est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son ancien usage."},{"voice":"female","text":"Quelle conception de la rénovation patrimoniale défend l'architecte ?"}],"audio":"q-30.mp3","audioSeconds":38.424,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution la conférencière recommande-t-elle ?","options":["Utiliser les économies prévues pour comparer la qualité des matériaux.","Tenir compte du climat et des usages pour mesurer les économies réelles.","Prendre les réglages précédents comme référence fixe pour les années suivantes.","Prendre la facture suivant les travaux comme mesure de leur efficacité propre."],"correct":"B","explanation":"Le résultat réel dépend du comportement des occupants et des conditions météorologiques.","transcript":"Question 31.\nAprès des travaux d'isolation, les consommations de chauffage peuvent diminuer moins que prévu. Cela ne signifie pas nécessairement que les matériaux sont inefficaces. Certains habitants choisissent de chauffer davantage des pièces auparavant trop froides. D'autres rencontrent des problèmes de réglage ou d'aération. Pour mesurer les économies, il faut comparer des périodes aux températures comparables et tenir compte de ces modifications de comportement. Une réduction théorique calculée avant les travaux ne doit pas être confondue avec la consommation réellement observée ensuite.\nQuelle précaution la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Après des travaux d'isolation, les consommations de chauffage peuvent diminuer moins que prévu. Cela ne signifie pas nécessairement que les matériaux sont inefficaces. Certains habitants choisissent de chauffer davantage des pièces auparavant trop froides. D'autres rencontrent des problèmes de réglage ou d'aération. Pour mesurer les économies, il faut comparer des périodes aux températures comparables et tenir compte de ces modifications de comportement. Une réduction théorique calculée avant les travaux ne doit pas être confondue avec la consommation réellement observée ensuite."},{"voice":"female","text":"Quelle précaution la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":37.599,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment les modèles de consommation devraient-ils être utilisés ?","options":["Présenter des scénarios et les ajuster selon les factures observées.","Fixer les charges sur la valeur moyenne prévue pour les années suivantes.","Annoncer les consommations prévues sans modifier les hypothèses de départ.","Choisir le scénario le plus prudent puis conserver ses paramètres initiaux."],"correct":"A","explanation":"La spécialiste propose des scénarios révisés à partir de données réelles.","transcript":"Question 32.\nVotre équipe prévoit la demande d'énergie d'un immeuble après rénovation. Les chiffres sont-ils suffisamment précis pour fixer toutes les charges futures ?\nNon. Ils servent à explorer des scénarios, car le nombre d'occupants, leurs habitudes et le climat peuvent changer. Nous confrontons chaque trimestre les prévisions aux factures réelles et ajustons les hypothèses. Communiquer une seule valeur comme si elle était garantie serait trompeur. Il vaut mieux présenter une fourchette et expliquer pourquoi le résultat pourrait s'écarter du modèle.\nComment les modèles de consommation devraient-ils être utilisés ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Votre équipe prévoit la demande d'énergie d'un immeuble après rénovation. Les chiffres sont-ils suffisamment précis pour fixer toutes les charges futures ?"},{"voice":"female","text":"Non. Ils servent à explorer des scénarios, car le nombre d'occupants, leurs habitudes et le climat peuvent changer. Nous confrontons chaque trimestre les prévisions aux factures réelles et ajustons les hypothèses. Communiquer une seule valeur comme si elle était garantie serait trompeur. Il vaut mieux présenter une fourchette et expliquer pourquoi le résultat pourrait s'écarter du modèle."},{"voice":"female","text":"Comment les modèles de consommation devraient-ils être utilisés ?"}],"audio":"q-32.mp3","audioSeconds":37.409,"slotSeconds":71},{"number":33,"kind":"commentary","question":"Quelle réserve la chroniqueuse émet-elle sur les chiffres du logement ?","options":["La baisse du loyer médian vient surtout des quartiers où les logements sont petits.","La baisse du loyer médian concerne surtout les logements récemment loués.","La baisse du loyer médian correspond surtout à une réduction des charges locatives.","La baisse du loyer médian ne décrit pas l'accès concret des familles au logement."],"correct":"D","explanation":"La chroniqueuse distingue la médiane des difficultés concrètes des ménages.","transcript":"Question 33.\nOn nous annonce que le loyer médian a légèrement baissé cette année. C'est une information importante, mais elle ne dit pas combien de familles trouvent effectivement un logement adapté à leurs revenus. Il faut aussi regarder les charges, la taille des logements disponibles et les quartiers où les prix évoluent autrement. Une médiane résume une distribution; elle ne peut remplacer l'analyse des ménages qui restent exclus du marché. Un prix moins élevé ne signifie pas toujours un accès plus facile.\nQuelle réserve la chroniqueuse émet-elle sur les chiffres du logement ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"On nous annonce que le loyer médian a légèrement baissé cette année. C'est une information importante, mais elle ne dit pas combien de familles trouvent effectivement un logement adapté à leurs revenus. Il faut aussi regarder les charges, la taille des logements disponibles et les quartiers où les prix évoluent autrement. Une médiane résume une distribution; elle ne peut remplacer l'analyse des ménages qui restent exclus du marché. Un prix moins élevé ne signifie pas toujours un accès plus facile."},{"voice":"female","text":"Quelle réserve la chroniqueuse émet-elle sur les chiffres du logement ?"}],"audio":"q-33.mp3","audioSeconds":33.512,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quel accord se dégage entre les intervenants ?","options":["Centraliser les demandes en ligne et garder le téléphone pour les urgences.","Préciser les demandes au téléphone puis communiquer leurs délais en ligne.","Suivre les demandes par plusieurs canaux tout en traitant les urgences à part.","Numéroter les demandes pour les traiter selon leur arrivée au guichet."],"correct":"C","explanation":"Ils retiennent un suivi transparent, par plusieurs canaux, sans ralentir les urgences.","transcript":"Question 34.\nNous parlons de l'entretien des immeubles collectifs.\nLes locataires signalent les pannes, mais ne savent pas toujours quand une intervention aura lieu.\nLes gestionnaires reçoivent de nombreuses demandes sans description précise, ce qui complique les priorités.\nNous pourrions instaurer un suivi des demandes avec un numéro et une réponse sur les délais prévus.\nEt conserver un téléphone pour les résidents qui n'utilisent pas Internet.\nOui, à condition que les urgences restent traitées immédiatement.\nQuel accord se dégage entre les intervenants ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Nous parlons de l'entretien des immeubles collectifs.","speaker":"female"},{"voice":"male","text":"Les locataires signalent les pannes, mais ne savent pas toujours quand une intervention aura lieu.","speaker":"male"},{"voice":"female","text":"Les gestionnaires reçoivent de nombreuses demandes sans description précise, ce qui complique les priorités.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions instaurer un suivi des demandes avec un numéro et une réponse sur les délais prévus.","speaker":"male"},{"voice":"female","text":"Et conserver un téléphone pour les résidents qui n'utilisent pas Internet.","speaker":"female_alt"},{"voice":"male","text":"Oui, à condition que les urgences restent traitées immédiatement.","speaker":"male"},{"voice":"female","text":"Quel accord se dégage entre les intervenants ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":35.84,"slotSeconds":71},{"number":35,"kind":"interview","question":"Pourquoi le spécialiste critique-t-il les thermostats entièrement automatisés ?","options":["Les réglages peuvent devenir moins efficaces dans les maisons aux horaires réguliers.","Les réglages peuvent ignorer les besoins d'une personne présente dans l'immeuble.","Les réglages peuvent perdre leur précision lorsque les habitants corrigent les données.","Les réglages peuvent augmenter les charges en comptant plusieurs fois les absences."],"correct":"B","explanation":"L'automatisation peut mal s'adapter aux horaires et besoins réels.","transcript":"Question 35.\nLes nouveaux thermostats adaptent le chauffage à la présence des occupants. N'est-ce pas une solution idéale ?\nPas toujours. Dans une maison, les habitudes sont relativement stables; dans un immeuble partagé, les horaires peuvent varier fortement. Si le système abaisse la température alors qu'une personne fragile est présente, il crée un inconfort. Il faut permettre aux occupants de comprendre les réglages, de les corriger et de signaler un problème. Une technologie performante ne dispense pas d'observer la vie quotidienne.\nPourquoi le spécialiste critique-t-il les thermostats entièrement automatisés ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Les nouveaux thermostats adaptent le chauffage à la présence des occupants. N'est-ce pas une solution idéale ?"},{"voice":"female","text":"Pas toujours. Dans une maison, les habitudes sont relativement stables; dans un immeuble partagé, les horaires peuvent varier fortement. Si le système abaisse la température alors qu'une personne fragile est présente, il crée un inconfort. Il faut permettre aux occupants de comprendre les réglages, de les corriger et de signaler un problème. Une technologie performante ne dispense pas d'observer la vie quotidienne."},{"voice":"female","text":"Pourquoi le spécialiste critique-t-il les thermostats entièrement automatisés ?"}],"audio":"q-35.mp3","audioSeconds":39.266,"slotSeconds":69},{"number":36,"kind":"interview","question":"À quelle condition la collecte de données est-elle acceptable ?","options":["Informer les habitants sur les mesures et leur donner un recours sur leurs usages.","Limiter les mesures aux absences des habitants et les conserver dans les contrats.","Informer les habitants des économies obtenues sans détailler les accès aux mesures.","Réserver les mesures au gestionnaire sans expliquer leur durée de conservation."],"correct":"A","explanation":"L'intervenante insiste sur une information claire et un contrôle des accès aux mesures.","transcript":"Question 36.\nVotre immeuble teste des capteurs de consommation. Pourquoi demandez-vous l'avis des habitants alors que les appareils ne filment personne ?\nDes données techniques peuvent révéler indirectement certaines habitudes, comme les périodes d'absence. Les résidents doivent savoir ce qui est mesuré, combien de temps les données seront conservées et qui pourra y accéder. Ils doivent aussi disposer d'un moyen de poser des questions et de contester un usage inapproprié. La transparence ne se résume pas à une phrase dans un contrat.\nÀ quelle condition la collecte de données est-elle acceptable ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre immeuble teste des capteurs de consommation. Pourquoi demandez-vous l'avis des habitants alors que les appareils ne filment personne ?"},{"voice":"female","text":"Des données techniques peuvent révéler indirectement certaines habitudes, comme les périodes d'absence. Les résidents doivent savoir ce qui est mesuré, combien de temps les données seront conservées et qui pourra y accéder. Ils doivent aussi disposer d'un moyen de poser des questions et de contester un usage inapproprié. La transparence ne se résume pas à une phrase dans un contrat."},{"voice":"female","text":"À quelle condition la collecte de données est-elle acceptable ?"}],"audio":"q-36.mp3","audioSeconds":34.982,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi l'enquêtrice conserve-t-elle des avis opposés sur le bruit ?","options":["L'exposition au chantier et les horaires de repos diffèrent selon les résidents.","Les appareils de mesure changeaient d'étage selon les visites des enquêteurs.","Les témoignages concernent des entreprises intervenant à des moments différents.","Les horaires des travaux annoncés aux résidents variaient selon les appartements."],"correct":"A","explanation":"Les expériences varient selon l'exposition et les habitudes de chaque résident.","transcript":"Question 37.\nCertains résidents disent que le chantier est supportable; d'autres parlent d'une gêne quotidienne. Comment expliquer cette différence ?\nLeurs appartements ne donnent pas tous sur la même façade et certaines personnes travaillent de nuit. Nous avons mesuré les niveaux sonores, mais nous devons aussi examiner la durée d'exposition et les horaires de repos. Le même bruit peut avoir des conséquences très différentes. Conserver les témoignages permet de comprendre cette répartition, sans renoncer aux données objectives des mesures.\nPourquoi l'enquêtrice conserve-t-elle des avis opposés sur le bruit ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Certains résidents disent que le chantier est supportable; d'autres parlent d'une gêne quotidienne. Comment expliquer cette différence ?"},{"voice":"female","text":"Leurs appartements ne donnent pas tous sur la même façade et certaines personnes travaillent de nuit. Nous avons mesuré les niveaux sonores, mais nous devons aussi examiner la durée d'exposition et les horaires de repos. Le même bruit peut avoir des conséquences très différentes. Conserver les témoignages permet de comprendre cette répartition, sans renoncer aux données objectives des mesures."},{"voice":"female","text":"Pourquoi l'enquêtrice conserve-t-elle des avis opposés sur le bruit ?"}],"audio":"q-37.mp3","audioSeconds":36.862,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe de l'aménagement urbain est présenté ?","options":["Réduire les distances peut accroître la consommation d'eau des quartiers végétalisés.","Limiter l'étalement peut allonger les trajets entre des logements trop serrés.","Réduire les surfaces minérales peut déplacer le bâti vers les terres agricoles.","Limiter l'étalement peut accroître la chaleur locale si les espaces plantés reculent."],"correct":"D","explanation":"La conférence montre que la densification peut nuire au confort local sans végétalisation.","transcript":"Question 38.\nDensifier les villes peut limiter l'étalement des constructions sur les terres agricoles. Mais si cette densification remplace systématiquement les cours plantées par des surfaces minérales, les quartiers deviennent plus chauds et moins agréables en été. L'objectif de réduction des distances parcourues ne doit donc pas faire oublier la qualité de vie locale. Il faut associer logements, transports, espaces ombragés et gestion de l'eau. Une solution qui semble écologique à l'échelle de la région peut produire des effets négatifs à l'échelle de la rue si l'on néglige ses conditions d'application.\nQuel paradoxe de l'aménagement urbain est présenté ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Densifier les villes peut limiter l'étalement des constructions sur les terres agricoles. Mais si cette densification remplace systématiquement les cours plantées par des surfaces minérales, les quartiers deviennent plus chauds et moins agréables en été. L'objectif de réduction des distances parcourues ne doit donc pas faire oublier la qualité de vie locale. Il faut associer logements, transports, espaces ombragés et gestion de l'eau. Une solution qui semble écologique à l'échelle de la région peut produire des effets négatifs à l'échelle de la rue si l'on néglige ses conditions d'application."},{"voice":"female","text":"Quel paradoxe de l'aménagement urbain est présenté ?"}],"audio":"q-38.mp3","audioSeconds":38.716,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle condition la responsable juge-t-elle nécessaire à la survie de la coopérative ?","options":["Obtenir une aide de lancement avant d'examiner les coûts du premier bâtiment.","Équilibrer le second bâtiment avant de prévoir les réparations du premier.","Satisfaire les demandes avant de former les membres aux décisions communes.","Assurer l'entretien et les décisions collectives avant d'ouvrir un autre bâtiment."],"correct":"D","explanation":"Elle veut assurer les ressources d'entretien et la gouvernance avant l'expansion.","transcript":"Question 39.\nVotre coopérative de logements accueille de nombreuses demandes. Pourquoi ne pas ouvrir immédiatement un second bâtiment ?\nNous devons d'abord vérifier notre capacité à entretenir les parties communes et à financer les grosses réparations. Le premier immeuble a bénéficié de subventions de lancement qui ne se répéteront pas nécessairement. Il nous faut aussi former de nouveaux membres aux décisions collectives, car la participation ne s'improvise pas. Un nouveau bâtiment serait une bonne nouvelle seulement si les logements existants restent abordables et correctement entretenus.\nQuelle condition la responsable juge-t-elle nécessaire à la survie de la coopérative ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre coopérative de logements accueille de nombreuses demandes. Pourquoi ne pas ouvrir immédiatement un second bâtiment ?"},{"voice":"female","text":"Nous devons d'abord vérifier notre capacité à entretenir les parties communes et à financer les grosses réparations. Le premier immeuble a bénéficié de subventions de lancement qui ne se répéteront pas nécessairement. Il nous faut aussi former de nouveaux membres aux décisions collectives, car la participation ne s'improvise pas. Un nouveau bâtiment serait une bonne nouvelle seulement si les logements existants restent abordables et correctement entretenus."},{"voice":"female","text":"Quelle condition la responsable juge-t-elle nécessaire à la survie de la coopérative ?"}],"audio":"q-39.mp3","audioSeconds":39.312,"slotSeconds":81}]},{"id":"tcf-listening-06","version":"tcf-listening-2026-11-test06-v3","title":"TCF Listening · Test 06","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La cliente examine les fruits disposés dans deux cagettes du marché.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Une vendeuse étiquette des bocaux sur une étagère. B. Une cliente compare les fruits de deux paniers. C. Une vendeuse ferme son stand à la fin du marché. D. Une cliente emballe les fruits pour un transport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une vendeuse étiquette des bocaux sur une étagère. B. Une cliente compare les fruits de deux paniers. C. Une vendeuse ferme son stand à la fin du marché. D. Une cliente emballe les fruits pour un transport."}],"audio":"q-01.mp3","audioSeconds":20.672,"slotSeconds":33,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Le fermier examine une conduite d'irrigation entre des rangées de cultures.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. L'agriculteur nettoie une machine après la récolte. B. L'agriculteur charge des sacs de grains dans une camionnette. C. L'agriculteur vérifie un tuyau d'arrosage. D. L'agriculteur récolte des pommes dans un verger.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'agriculteur nettoie une machine après la récolte. B. L'agriculteur charge des sacs de grains dans une camionnette. C. L'agriculteur vérifie un tuyau d'arrosage. D. L'agriculteur récolte des pommes dans un verger."}],"audio":"q-02.mp3","audioSeconds":20.544,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Une personne dépose des pains sur une balance dans une cuisine associative.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. Un bénévole transporte des pains vers une table. B. Un bénévole prépare des affiches pour une collecte. C. Un bénévole range des plats dans un réfrigérateur. D. Un bénévole pèse du pain récupéré dans une boulangerie.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Un bénévole transporte des pains vers une table. B. Un bénévole prépare des affiches pour une collecte. C. Un bénévole range des plats dans un réfrigérateur. D. Un bénévole pèse du pain récupéré dans une boulangerie."}],"audio":"q-03.mp3","audioSeconds":20.288,"slotSeconds":34,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Le cuisinier utilise une planche et un couteau pour préparer les légumes.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Le cuisinier découpe des légumes sur un plan de travail. B. Le cuisinier lave des assiettes après le service. C. Le cuisinier range les ingrédients dans un placard. D. Le cuisinier apporte un plateau au comptoir.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le cuisinier découpe des légumes sur un plan de travail. B. Le cuisinier lave des assiettes après le service. C. Le cuisinier range les ingrédients dans un placard. D. Le cuisinier apporte un plateau au comptoir."}],"audio":"q-04.mp3","audioSeconds":20.033,"slotSeconds":33,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond à la provenance des tomates.","transcript":"Question 5.\nCes tomates viennent-elles de votre exploitation ?\nA. Elles se conservent trois jours à température ambiante. B. Oui, nous les cultivons à quelques kilomètres d'ici. C. Elles seront disponibles à partir de vendredi. D. Elles coûtent deux euros cinquante le kilo.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Ces tomates viennent-elles de votre exploitation ?"},{"voice":"male","text":"A. Elles se conservent trois jours à température ambiante. B. Oui, nous les cultivons à quelques kilomètres d'ici. C. Elles seront disponibles à partir de vendredi. D. Elles coûtent deux euros cinquante le kilo."}],"audio":"q-05.mp3","audioSeconds":21.502,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique comment effectuer la réservation du panier.","transcript":"Question 6.\nPuis-je réserver un panier de légumes pour samedi ?\nA. Oui, inscrivez votre nom avant jeudi soir. B. Oui, le marché ouvre plus tard samedi. C. Les paniers coûtent moins cher en été. D. Les légumes sont récoltés dès l'aube.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Puis-je réserver un panier de légumes pour samedi ?"},{"voice":"female","text":"A. Oui, inscrivez votre nom avant jeudi soir. B. Oui, le marché ouvre plus tard samedi. C. Les paniers coûtent moins cher en été. D. Les légumes sont récoltés dès l'aube."}],"audio":"q-06.mp3","audioSeconds":18.506,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La troisième proposition donne un conseil concret de conservation.","transcript":"Question 7.\nVous connaissez la meilleure façon de conserver ces herbes fraîches ?\nA. Le potager est situé derrière le bâtiment. B. La livraison arrive au marché dans une heure. C. Gardez-les au frais dans un linge légèrement humide. D. La récolte a commencé tôt ce matin.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Vous connaissez la meilleure façon de conserver ces herbes fraîches ?"},{"voice":"male","text":"A. Le potager est situé derrière le bâtiment. B. La livraison arrive au marché dans une heure. C. Gardez-les au frais dans un linge légèrement humide. D. La récolte a commencé tôt ce matin."}],"audio":"q-07.mp3","audioSeconds":20.817,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur confirme que la dégustation est incluse.","transcript":"Question 8.\nEst-ce que la dégustation de ce soir est comprise dans le billet ?\nA. Elle commence à dix-neuf heures en salle trois. B. Elle sera animée par deux producteurs régionaux. C. Elle proposera cinq recettes végétariennes différentes. D. Oui, l'entrée comprend la dégustation des produits.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Est-ce que la dégustation de ce soir est comprise dans le billet ?"},{"voice":"female","text":"A. Elle commence à dix-neuf heures en salle trois. B. Elle sera animée par deux producteurs régionaux. C. Elle proposera cinq recettes végétariennes différentes. D. Oui, l'entrée comprend la dégustation des produits."}],"audio":"q-08.mp3","audioSeconds":20.614,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quand la distribution des paniers aura-t-elle lieu ?","options":["Samedi, de neuf heures à onze heures au marché.","Vendredi, de huit heures à dix heures au hangar.","Samedi, de dix heures à midi au hangar habituel.","Samedi, de huit heures à dix heures au marché."],"correct":"D","explanation":"La distribution est avancée et se tient samedi de huit à dix heures.","transcript":"Question 9.\nEn raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi.\nQuand la distribution des paniers aura-t-elle lieu ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"En raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi."},{"voice":"female","text":"Quand la distribution des paniers aura-t-elle lieu ?"}],"audio":"q-09.mp3","audioSeconds":22.274,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi la restauratrice modifie-t-elle sa commande ?","options":["Le prix des courgettes dépasse celui prévu pour le menu du lendemain.","La livraison des courgettes est reportée après le service du déjeuner.","Les aubergines commandées seront remplacées par des courgettes.","La quantité de courgettes disponible est inférieure à sa commande."],"correct":"D","explanation":"Le fournisseur ne peut livrer que dix kilos de courgettes au lieu de quinze.","transcript":"Question 10.\nBonjour, je vous ai commandé quinze kilos de courgettes pour demain.\nNous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte.\nDans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu.\nOui, je vous livrerai les deux produits demain matin.\nTrès bien, je préviens la cuisine.\nPourquoi la restauratrice modifie-t-elle sa commande ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"Bonjour, je vous ai commandé quinze kilos de courgettes pour demain."},{"voice":"male","text":"Nous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte."},{"voice":"female","text":"Dans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu."},{"voice":"male","text":"Oui, je vous livrerai les deux produits demain matin."},{"voice":"female","text":"Très bien, je préviens la cuisine."},{"voice":"female","text":"Pourquoi la restauratrice modifie-t-elle sa commande ?"}],"audio":"q-10.mp3","audioSeconds":26.665,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment faut-il participer à l'atelier culinaire ?","options":["Renvoyer après jeudi le formulaire remis par l'association.","Réserver avant samedi auprès de l'animateur à la médiathèque.","Déposer jeudi le formulaire à l'arrivée à la médiathèque.","Remplir avant jeudi le formulaire proposé à la médiathèque."],"correct":"D","explanation":"Une inscription avant jeudi sur formulaire est indispensable.","transcript":"Question 11.\nL'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé.\nComment faut-il participer à l'atelier culinaire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"L'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé."},{"voice":"female","text":"Comment faut-il participer à l'atelier culinaire ?"}],"audio":"q-11.mp3","audioSeconds":25.49,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quel arrangement est convenu pour la livraison ?","options":["Livrer les fromages samedi soir et les mettre aussitôt au frais.","Livrer les fromages samedi soir et les refroidir le lendemain.","Livrer les fromages dimanche soir après le départ des cyclistes.","Livrer les fromages dimanche matin avant la fermeture du quai."],"correct":"A","explanation":"La livraison est avancée à samedi soir avec conservation immédiate au froid.","transcript":"Question 12.\nNotre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche.\nLe quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?\nOui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais.\nNous aurons une personne sur place pour ouvrir la chambre froide.\nQuel arrangement est convenu pour la livraison ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Notre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche."},{"voice":"female","text":"Le quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?"},{"voice":"male","text":"Oui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais."},{"voice":"female","text":"Nous aurons une personne sur place pour ouvrir la chambre froide."},{"voice":"female","text":"Quel arrangement est convenu pour la livraison ?"}],"audio":"q-12.mp3","audioSeconds":26.874,"slotSeconds":44},{"number":13,"kind":"announcement","question":"Quelle précaution est demandée aux vendeurs ?","options":["Transférer les denrées sensibles sur un étal avant l'arrivée de l'agent.","Regrouper les denrées sensibles avec les fruits secs pour le contrôle.","Laisser les denrées sensibles dans leurs appareils jusqu'au contrôle.","Transporter les denrées sensibles hors du marché pendant le contrôle."],"correct":"C","explanation":"Les vendeurs doivent conserver les produits réfrigérés dans les équipements appropriés.","transcript":"Question 13.\nLe marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés.\nQuelle précaution est demandée aux vendeurs ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés."},{"voice":"female","text":"Quelle précaution est demandée aux vendeurs ?"}],"audio":"q-13.mp3","audioSeconds":22.401,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Pourquoi le menu du jour a-t-il changé ?","options":["La recette du gratin a été remplacée après une demande du client.","La livraison contenait d'autres légumes que ceux commandés.","La livraison prévue pour le gratin a été retardée jusqu'au soir.","La recette prévue contenait un allergène omis sur le tableau."],"correct":"B","explanation":"Les ingrédients reçus ne correspondent pas à la commande prévue.","transcript":"Question 14.\nJe pensais que vous serviez un gratin de pommes de terre aujourd'hui.\nC'était prévu, mais notre livraison est arrivée avec des patates douces à la place.\nVous avez changé la recette ?\nOui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise.\nD'accord, je vais essayer cette soupe.\nPourquoi le menu du jour a-t-il changé ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Je pensais que vous serviez un gratin de pommes de terre aujourd'hui."},{"voice":"female","text":"C'était prévu, mais notre livraison est arrivée avec des patates douces à la place."},{"voice":"male","text":"Vous avez changé la recette ?"},{"voice":"female","text":"Oui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise."},{"voice":"male","text":"D'accord, je vais essayer cette soupe."},{"voice":"female","text":"Pourquoi le menu du jour a-t-il changé ?"}],"audio":"q-14.mp3","audioSeconds":26.451,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?","options":["Les jours de livraison changent selon les disponibilités des cantines.","Les commandes reçues restent inférieures aux volumes déjà récoltés.","Les trajets groupés multiplient les retards par rapport aux trajets séparés.","Les volumes récoltés varient et compliquent les engagements de livraison."],"correct":"D","explanation":"L'incertitude sur les récoltes rend difficile le respect des volumes convenus.","transcript":"Question 15.\nUn groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute.\nQuel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Un groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute."},{"voice":"female","text":"Quel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?"}],"audio":"q-15.mp3","audioSeconds":28.462,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi la personne chargée de la cantine demande-t-elle un autre jour ?","options":["La cantine ne pourra pas stocker les pommes avant le service du mercredi.","Le fournisseur ne pourra pas récolter les pommes avant mardi après-midi.","Le cuisinier ne pourra pas signer le bordereau à son arrivée mercredi.","La cuisine ne pourra pas recevoir la livraison pendant son entretien mardi."],"correct":"D","explanation":"La cantine ferme mardi pour entretien et fixe une livraison mercredi tôt.","transcript":"Question 16.\nLe fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien.\nNous pourrions venir mercredi matin, avant la préparation du déjeuner.\nMercredi, oui, à condition d'arriver avant huit heures.\nJe note sept heures trente. Il faudra quelqu'un pour signer le bordereau.\nLe chef sera présent.\nPourquoi la personne chargée de la cantine demande-t-elle un autre jour ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Le fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien."},{"voice":"male","text":"Nous pourrions venir mercredi matin, avant la préparation du déjeuner."},{"voice":"female","text":"Mercredi, oui, à condition d'arriver avant huit heures."},{"voice":"male","text":"Je note sept heures trente. Il faudra quelqu'un pour signer le bordereau."},{"voice":"female","text":"Le chef sera présent."},{"voice":"female","text":"Pourquoi la personne chargée de la cantine demande-t-elle un autre jour ?"}],"audio":"q-16.mp3","audioSeconds":27.258,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Qu'est-ce qui sera récupéré par la collecte ?","options":["Les fruits et légumes invendus qui restent propres à la consommation.","Les fruits et légumes invendus gardés pour la réouverture du marché.","Les fruits et légumes abîmés déjà séparés pour préparer le compost.","Les fruits et légumes abîmés récupérables après un traitement au dépôt."],"correct":"A","explanation":"La collecte alimentaire concerne les invendus encore consommables.","transcript":"Question 17.\nLa collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes.\nQu'est-ce qui sera récupéré par la collecte ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes."},{"voice":"female","text":"Qu'est-ce qui sera récupéré par la collecte ?"}],"audio":"q-17.mp3","audioSeconds":26.186,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi le client souhaite-t-il parler au responsable ?","options":["Le panier reçu manque de lait alors que son abonnement prévoit ces produits.","Le panier reçu contient du lait malgré la formule choisie dans son dossier.","Le panier prévu a été annulé après son changement de formule alimentaire.","Le panier de remplacement a été livré avant la modification de son dossier."],"correct":"B","explanation":"Le panier livré ne respecte pas le choix sans produits laitiers.","transcript":"Question 18.\nBonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait.\nJe vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement.\nPouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas.\nBien sûr, notre responsable vous contactera aujourd'hui.\nPourquoi le client souhaite-t-il parler au responsable ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait."},{"voice":"female","text":"Je vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement."},{"voice":"male","text":"Pouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas."},{"voice":"female","text":"Bien sûr, notre responsable vous contactera aujourd'hui."},{"voice":"female","text":"Pourquoi le client souhaite-t-il parler au responsable ?"}],"audio":"q-18.mp3","audioSeconds":29.794,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi les visites de la ferme se font-elles en petits groupes ?","options":["Pour réserver les échanges aux visiteurs connaissant déjà les animaux.","Pour éviter aux accompagnateurs de répondre aux questions près des animaux.","Pour faciliter l'écoute et les déplacements sans gêner les soins aux animaux.","Pour limiter la durée des soins durant les explications des accompagnateurs."],"correct":"C","explanation":"La limitation facilite l'écoute et la circulation près des animaux.","transcript":"Question 19.\nLors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes.\nPourquoi les visites de la ferme se font-elles en petits groupes ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Lors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes."},{"voice":"female","text":"Pourquoi les visites de la ferme se font-elles en petits groupes ?"}],"audio":"q-19.mp3","audioSeconds":24.007,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Qu'est-ce qui préoccupe le responsable du restaurant ?","options":["Le besoin de modifier le matériel pour préparer les légumes du voisin.","Le coût des légumes locaux pendant la fermeture saisonnière du restaurant.","La difficulté à former les cuisiniers avant le changement de fournisseur.","La difficulté à proposer les mêmes légumes tout au long de l'année."],"correct":"D","explanation":"Il craint de ne pas disposer des mêmes légumes en toute saison.","transcript":"Question 20.\nNous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante.\nC'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas.\nJustement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières.\nNous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions.\nQu'est-ce qui préoccupe le responsable du restaurant ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Nous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante."},{"voice":"female","text":"C'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas."},{"voice":"male","text":"Justement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières."},{"voice":"female","text":"Nous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions."},{"voice":"female","text":"Qu'est-ce qui préoccupe le responsable du restaurant ?"}],"audio":"q-20.mp3","audioSeconds":28.029,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pourquoi les bénévoles doivent-ils communiquer leur disponibilité ?","options":["Pour choisir les marchés où les bénévoles souhaitent faire leurs achats.","Pour répartir les équipes entre les marchés aux heures de fermeture.","Pour fixer les horaires d'ouverture des marchés pendant la collecte.","Pour connaître les quantités d'invendus avant la fermeture des marchés."],"correct":"B","explanation":"Les horaires des bénévoles permettent d'assurer une collecte dans chaque marché.","transcript":"Question 21.\nLa banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte.\nPourquoi les bénévoles doivent-ils communiquer leur disponibilité ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"La banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte."},{"voice":"female","text":"Pourquoi les bénévoles doivent-ils communiquer leur disponibilité ?"}],"audio":"q-21.mp3","audioSeconds":26.987,"slotSeconds":52},{"number":22,"kind":"interview","question":"Quel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?","options":["Les commandes qui libèrent les producteurs des contraintes liées aux récoltes.","Les échanges qui rapprochent les réalités des producteurs et des habitants.","Les paniers qui proposent aux habitants les mêmes produits à chaque saison.","Les ventes qui assurent aux producteurs des revenus réguliers chaque semaine."],"correct":"B","explanation":"Elle insiste sur le dialogue et une meilleure compréhension des réalités agricoles.","transcript":"Question 22.\nVous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?\nC'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction.\nQuel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?"},{"voice":"female","text":"C'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction."},{"voice":"female","text":"Quel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?"}],"audio":"q-22.mp3","audioSeconds":35.585,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Quel accord se dessine pour les menus scolaires ?","options":["Fixer les menus annuels avant de négocier les quantités avec les producteurs.","Étendre les contrats à tous les produits avant d'observer les restes des repas.","Tester des produits de saison en suivant les restes et les réactions des élèves.","Conserver les menus habituels pour mesurer la satisfaction des familles."],"correct":"C","explanation":"Les participants proposent une expérimentation saisonnière avec suivi du gaspillage et des réactions.","transcript":"Question 23.\nNous discutons de la place des aliments locaux dans les cantines.\nPour les producteurs, des contrats réguliers faciliteraient les investissements.\nDu côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables.\nEt les parents veulent des repas équilibrés et un coût maîtrisé.\nNous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine.\nD'accord, si les équipes évaluent aussi les restes et les réactions des élèves.\nQuel accord se dessine pour les menus scolaires ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Nous discutons de la place des aliments locaux dans les cantines.","speaker":"female"},{"voice":"male","text":"Pour les producteurs, des contrats réguliers faciliteraient les investissements.","speaker":"male"},{"voice":"female","text":"Du côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables.","speaker":"female_alt"},{"voice":"male","text":"Et les parents veulent des repas équilibrés et un coût maîtrisé.","speaker":"male_alt"},{"voice":"female","text":"Nous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine.","speaker":"female_alt"},{"voice":"male","text":"D'accord, si les équipes évaluent aussi les restes et les réactions des élèves.","speaker":"male"},{"voice":"female","text":"Quel accord se dessine pour les menus scolaires ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":33.463,"slotSeconds":71},{"number":24,"kind":"interview","question":"Quelle limite l'économiste relève-t-elle dans les statistiques ?","options":["Le public interrogé était probablement déjà sensible aux produits locaux.","Les répondants habitent surtout des communes éloignées des producteurs.","Les répondants déclarent leurs achats à partir de leurs justificatifs de caisse.","Les répondants se prononcent après avoir comparé leurs dépenses alimentaires."],"correct":"A","explanation":"L'échantillon sélectionné pendant un festival spécialisé n'est pas représentatif.","transcript":"Question 24.\nUne enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?\nNous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence.\nQuelle limite l'économiste relève-t-elle dans les statistiques ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Une enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?"},{"voice":"female","text":"Nous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence."},{"voice":"female","text":"Quelle limite l'économiste relève-t-elle dans les statistiques ?"}],"audio":"q-24.mp3","audioSeconds":36.835,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Quel problème le reportage souligne-t-il ?","options":["La régularité des commandes pousse les fermes à multiplier les trajets.","La centralisation des commandes éloigne les restaurateurs des producteurs.","Le regroupement des tournées reste difficile dans les zones peu denses.","La livraison groupée oblige les restaurants à acheter des volumes excessifs."],"correct":"C","explanation":"La faible densité des trajets rend certaines livraisons peu efficaces.","transcript":"Question 25.\nDans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée.\nMais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux.\nLa coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine.\nQuel problème le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée."},{"voice":"male","text":"Mais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux."},{"voice":"female","text":"La coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine."},{"voice":"female","text":"Quel problème le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":37.032,"slotSeconds":72},{"number":26,"kind":"interview","question":"Pourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?","options":["Les seuils d'arrosage doivent privilégier la quantité d'eau disponible.","Les seuils d'arrosage doivent tenir compte des sols et des cultures.","Les seuils d'arrosage doivent dépendre du modèle de capteur installé.","Les seuils d'arrosage doivent rester identiques entre les parcelles voisines."],"correct":"B","explanation":"L'agronome explique que sol et cultures doivent être pris en compte dans les réglages.","transcript":"Question 26.\nDes capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?\nLes mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs.\nPourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Des capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?"},{"voice":"female","text":"Les mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs."},{"voice":"female","text":"Pourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?"}],"audio":"q-26.mp3","audioSeconds":39.016,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quelle décision prend le responsable des achats ?","options":["Commander les mêmes pommes pour les deux recettes en réduisant les portions servies.","Acheter les petites pommes pour les tranches et garder les grandes pour les compotes.","Acheter les petites pommes pour les compotes et garder les autres pour les tranches.","Garder le fournisseur habituel pour les compotes et reporter les autres desserts."],"correct":"C","explanation":"Ils choisissent deux fournisseurs selon les usages culinaires.","transcript":"Question 27.\nLe fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude.\nCela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches.\nAlors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste.\nJe vérifierai les quantités nécessaires pour chaque recette.\nQuelle décision prend le responsable des achats ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Le fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude."},{"voice":"female","text":"Cela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches."},{"voice":"male","text":"Alors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste."},{"voice":"female","text":"Je vérifierai les quantités nécessaires pour chaque recette."},{"voice":"female","text":"Quelle décision prend le responsable des achats ?"}],"audio":"q-27.mp3","audioSeconds":26.56,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur le chercheur identifie-t-il dans la préparation du projet ?","options":["La formation des bénévoles a été organisée avant le choix des horaires de collecte.","La chambre froide a été dimensionnée selon les besoins des commerçants donateurs.","La capacité de stockage a été étudiée avant les circuits réels de redistribution.","La redistribution a été accélérée avant la mise en service de la chambre froide."],"correct":"C","explanation":"Le projet a privilégié la capacité de stockage sans résoudre les problèmes de circulation et tri.","transcript":"Question 28.\nVotre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?\nNous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins.\nQuelle erreur le chercheur identifie-t-il dans la préparation du projet ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Votre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?"},{"voice":"female","text":"Nous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins."},{"voice":"female","text":"Quelle erreur le chercheur identifie-t-il dans la préparation du projet ?"}],"audio":"q-28.mp3","audioSeconds":41.228,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quel désaccord oppose principalement les deux invités ?","options":["La rigidité des objectifs imposés pour la part locale des approvisionnements.","La durée des contrats conclus entre les cantines et les producteurs régionaux.","La participation des cantines aux investissements des producteurs régionaux.","La répartition des emplois agricoles créés autour des établissements scolaires."],"correct":"A","explanation":"Ils divergent sur la rigidité d'une proportion locale obligatoire.","transcript":"Question 29.\nFaut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?\nCela renforcerait les emplois agricoles de la région et raccourcirait certains transports.\nMais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés.\nJe ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs.\nNous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé.\nQuel désaccord oppose principalement les deux invités ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Faut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?","speaker":"female"},{"voice":"male","text":"Cela renforcerait les emplois agricoles de la région et raccourcirait certains transports.","speaker":"male"},{"voice":"female","text":"Mais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés.","speaker":"female_alt"},{"voice":"male","text":"Je ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs.","speaker":"male"},{"voice":"female","text":"Nous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé.","speaker":"female_alt"},{"voice":"female","text":"Quel désaccord oppose principalement les deux invités ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":38.478,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine alimentaire défend la spécialiste ?","options":["Transmettre les gestes anciens en laissant les recettes évoluer avec les usages.","Adapter les recettes actuelles sans conserver les techniques devenues rares.","Fixer une version des recettes pour faciliter leur transmission aux générations.","Conserver les ingrédients anciens en modernisant les gestes de préparation."],"correct":"A","explanation":"La spécialiste valorise la transmission avec possibilité d'évolution.","transcript":"Question 30.\nVous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?\nLes recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher.\nQuelle conception du patrimoine alimentaire défend la spécialiste ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Vous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?"},{"voice":"female","text":"Les recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher."},{"voice":"female","text":"Quelle conception du patrimoine alimentaire défend la spécialiste ?"}],"audio":"q-30.mp3","audioSeconds":36.828,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?","options":["Séparer l'effet de l'outil de celui des autres changements survenus.","Garder les parcelles les plus productives pour évaluer les nouveaux outils.","Attribuer à l'outil les gains répétés après son adoption dans plusieurs fermes.","Comparer les rendements récents sans intégrer les saisons moins favorables."],"correct":"A","explanation":"La conférencière recommande de contrôler les autres facteurs influençant les rendements.","transcript":"Question 31.\nDans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité.\nQuelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Dans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité."},{"voice":"female","text":"Quelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?"}],"audio":"q-31.mp3","audioSeconds":39.201,"slotSeconds":74},{"number":32,"kind":"interview","question":"Comment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?","options":["Présenter le volume le plus probable comme la base définitive des commandes.","Présenter une fourchette et la réviser lorsque de nouvelles observations arrivent.","Présenter le scénario favorable puis le confirmer à la fin de chaque saison.","Présenter un chiffre précis en réservant l'incertitude aux échanges internes."],"correct":"B","explanation":"Il préconise une fourchette explicitée et des mises à jour.","transcript":"Question 32.\nVous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?\nNous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée.\nComment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?"},{"voice":"female","text":"Nous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée."},{"voice":"female","text":"Comment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?"}],"audio":"q-32.mp3","audioSeconds":33.478,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","options":["La baisse des déchets jetés provient surtout d'un changement dans les produits vendus.","La baisse des déchets jetés ne prouve pas que les aliments soient consommés.","La baisse des déchets jetés permet de prévoir les besoins alimentaires des ménages.","La baisse des déchets jetés concerne surtout les magasins proches des associations."],"correct":"B","explanation":"Elle souligne la différence entre produits retirés des déchets et produits réellement consommés.","transcript":"Question 33.\nUne enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage.\nQuelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Une enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage."},{"voice":"female","text":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?"}],"audio":"q-33.mp3","audioSeconds":34.383,"slotSeconds":67},{"number":34,"kind":"roundtable","question":"Quel compromis est finalement proposé ?","options":["Convenir de contrats annuels garantissant la même variété à chaque livraison.","Conserver les recettes habituelles et ajuster les contrats aux quantités livrées.","Convenir de contrats saisonniers prévoyant des substitutions acceptées à l'avance.","Accepter les substitutions après les livraisons selon la place dans les cuisines."],"correct":"C","explanation":"Ils s'entendent sur des contrats souples prévoyant des substitutions.","transcript":"Question 34.\nUne table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs.\nNous aimerions des commandes stables pour planifier nos semis.\nLes cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés.\nSi une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés.\nNous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance.\nÀ condition de suivre aussi les quantités réellement consommées.\nD'accord, testons cette formule sur un trimestre.\nQuel compromis est finalement proposé ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Une table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs.","speaker":"female"},{"voice":"male","text":"Nous aimerions des commandes stables pour planifier nos semis.","speaker":"male"},{"voice":"female","text":"Les cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés.","speaker":"female_alt"},{"voice":"male","text":"Si une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés.","speaker":"male"},{"voice":"female","text":"Nous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance.","speaker":"female_alt"},{"voice":"male","text":"À condition de suivre aussi les quantités réellement consommées.","speaker":"male"},{"voice":"female","text":"D'accord, testons cette formule sur un trimestre.","speaker":"female_alt"},{"voice":"female","text":"Quel compromis est finalement proposé ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":40.934,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée l'ingénieure remet-elle en question ?","options":["Un contenant réutilisable a nécessairement un meilleur bilan environnemental.","Le lavage contribue au bilan environnemental des contenants réutilisables.","Le bilan d'un contenant dépend du nombre de cycles de retour et de lavage.","Le transport de retour peut diminuer l'intérêt environnemental d'un contenant."],"correct":"A","explanation":"Elle conteste la supériorité environnementale automatique du réemploi, sans bilan complet.","transcript":"Question 35.\nLes nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?\nIl faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact.\nQuelle idée l'ingénieure remet-elle en question ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Les nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?"},{"voice":"female","text":"Il faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact."},{"voice":"female","text":"Quelle idée l'ingénieure remet-elle en question ?"}],"audio":"q-35.mp3","audioSeconds":36.34,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition les habitants profitent-ils réellement du jardin partagé ?","options":["Lorsque chaque membre justifie ses absences avant de choisir ses tâches.","Lorsque les règles et les tâches permettent diverses façons de participer.","Lorsque les récoltes récompensent les membres selon leurs heures de travail.","Lorsque les décisions reviennent aux membres présents aux réunions régulières."],"correct":"B","explanation":"La participation doit être ouverte et adaptée aux différentes contraintes.","transcript":"Question 36.\nLe jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?\nPas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide.\nÀ quelle condition les habitants profitent-ils réellement du jardin partagé ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Le jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?"},{"voice":"female","text":"Pas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide."},{"voice":"female","text":"À quelle condition les habitants profitent-ils réellement du jardin partagé ?"}],"audio":"q-36.mp3","audioSeconds":36.601,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","options":["Pour relier les souvenirs aux positions des témoins et les confronter aux archives.","Pour retenir les souvenirs les plus partagés au moment de constituer les archives.","Pour établir les dates en privilégiant les souvenirs des anciens responsables.","Pour compléter les archives en écartant les récits incompatibles entre eux."],"correct":"A","explanation":"Elle examine les divergences à la lumière des positions des témoins et des archives.","transcript":"Question 37.\nLes anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?\nNous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions.\nPourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?"},{"voice":"female","text":"Nous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions."},{"voice":"female","text":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":36.543,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe le conférencier décrit-il ?","options":["L'affluence peut réduire les prix en multipliant les présentations pour les touristes.","L'affluence peut empêcher les producteurs de vendre aux visiteurs leurs produits.","L'affluence peut faire disparaître la réputation régionale des produits du terroir.","L'affluence peut détourner le marché des besoins qui lui donnaient sa valeur locale."],"correct":"D","explanation":"L'affluence peut transformer le marché au détriment de la population locale.","transcript":"Question 38.\nPromouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale.\nQuel paradoxe le conférencier décrit-il ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"male","text":"Promouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale."},{"voice":"female","text":"Quel paradoxe le conférencier décrit-il ?"}],"audio":"q-38.mp3","audioSeconds":37.553,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?","options":["Conserver les équipes du départ pour stabiliser le modèle dans chaque quartier.","Augmenter les repas servis avant de revoir la répartition du travail des bénévoles.","Établir les coûts et répartir les ressources avant de reproduire le modèle ailleurs.","Reproduire l'organisation actuelle puis comparer les coûts entre les quartiers."],"correct":"C","explanation":"Elle veut établir un modèle durable avant de le reproduire.","transcript":"Question 39.\nVotre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?\nParce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières.\nQuelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?"},{"voice":"female","text":"Parce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières."},{"voice":"female","text":"Quelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?"}],"audio":"q-39.mp3","audioSeconds":40.107,"slotSeconds":82}]}]$review_papers$::jsonb;
 item jsonb;
 previous_paper jsonb;
 preserved_before jsonb;
 preserved_after jsonb;
 old_papers_before jsonb;
 old_papers_after jsonb;
 other_publications_before jsonb;
 other_publications_after jsonb;
 rpc_before text;
 rpc_after text;
begin
 perform pg_advisory_xact_lock(hashtext('hzad-listening-03-06-owner-review-v3'));
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t)) into preserved_before;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_papers_before
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test03-v3','tcf-listening-2026-11-test04-v3','tcf-listening-2026-11-test05-v3','tcf-listening-2026-11-test06-v3');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_publications_before
  from academy_tcf_listening.published where test_id not in ('tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into rpc_before;
 for item in select value from jsonb_array_elements(wanted) loop
  select content into previous_paper from academy_tcf_listening.papers
   where id=item->>'id' and version=item->>'version';
  if found and previous_paper is distinct from item then raise exception 'Immutable candidate content differs: %',item->>'id';end if;
  if jsonb_array_length(item->'questions')<>39 or (item->>'seconds')::int<>2100
   or (select sum((q->>'slotSeconds')::numeric) from jsonb_array_elements(item->'questions') q)<>2100
   or exists(select 1 from jsonb_array_elements(item->'questions') q
    where jsonb_array_length(q->'options')<>4 or q->>'correct' not in ('A','B','C','D')
     or coalesce((q->>'audioSeconds')::numeric,0)<=0 or (q->>'audioSeconds')::numeric+12>(q->>'slotSeconds')::numeric)
   then raise exception 'Incomplete question bank: %',item->>'id';end if;
  select content into previous_paper from academy_tcf_listening.papers
   where id=item->>'id' and version='tcf-listening-2026-11-test'||right(item->>'id',2)||'-v1';
  if not found then raise exception 'Historical paper missing: %',item->>'id';end if;
  if exists(select 1 from jsonb_array_elements(item->'questions') q
   join jsonb_array_elements(previous_paper->'questions') oldq on oldq->>'number'=q->>'number'
   where oldq->'slotSeconds' is distinct from q->'slotSeconds' or oldq->'kind' is distinct from q->'kind')
   then raise exception 'Historical format/timing changed: %',item->>'id';end if;
  insert into academy_tcf_listening.papers(id,version,content)
   values(item->>'id',item->>'version',item) on conflict(id,version) do nothing;
  insert into academy_tcf_listening.published(test_id,version)
   values(item->>'id',item->>'version') on conflict(test_id) do update set version=excluded.version
   where academy_tcf_listening.published.version is distinct from excluded.version;
 end loop;
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t)) into preserved_after;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_papers_after
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test03-v3','tcf-listening-2026-11-test04-v3','tcf-listening-2026-11-test05-v3','tcf-listening-2026-11-test06-v3');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_publications_after
  from academy_tcf_listening.published where test_id not in ('tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into rpc_after;
 if preserved_before is distinct from preserved_after or old_papers_before is distinct from old_papers_after
  or other_publications_before is distinct from other_publications_after or rpc_before is distinct from rpc_after
  then raise exception 'Existing student data, papers, publication or engine changed';end if;
 if exists(select 1 from jsonb_array_elements(wanted) p where not exists(
  select 1 from academy_tcf_listening.papers b join academy_tcf_listening.published v on v.test_id=b.id and v.version=b.version
   where b.id=p->>'id' and b.version=p->>'version' and b.content=p)) then raise exception 'Exact candidate publication failed';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='academy_tcf_listening' and c.relkind='r' and not c.relrowsecurity)
  or has_table_privilege('authenticated','academy_tcf_listening.papers','select')
  or has_table_privilege('anon','academy_tcf_listening.papers','select')
  then raise exception 'Listening RLS/private bank protection differs';end if;
end;
$publish_review$;
